const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const F={"backend/src/controllers/kai.controller.ts": "// ============================================================\n// KIRO — Complete Controller (10/10)\n// Path: backend/src/controllers/kai.controller.ts\n// ============================================================\nimport { Request, Response } from \"express\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport { PrismaClient } from \"@prisma/client\";\nimport {\n  callClaude, detectIntent, generateTitle, getQuickActions,\n} from \"../services/kai.service\";\nimport { validateAction, translateError, describeAction } from \"../utils/kai.actions\";\nimport { scrapeAnyUrl, researchMarket, getTrendingProducts, calculateProfit } from \"../services/kai.scraper.service\";\n// Note: getStoreContext replaced by getDeepContext globally\nimport { getDeepContext } from \"../services/kai.context\";\nimport { buildStoreBrain, decomposeGoal } from \"../services/kai.brain\";\nimport { buildIntelligencePrompt } from \"../services/kai.intelligence\";\nimport {\n  extractMemoriesFromConversation, getMemories, saveMemory,\n  deleteMemory, getActiveGoals, analyzeBrandVoice, getMemoryContext,\n  getRelevantMemories, buildCrossSessionContext, summarizeAndSaveConversation,\n} from \"../services/kai.memory.service\";\nimport {\n  getUnreadAlerts, markAlertRead, analyzeStore,\n} from \"../services/kai.pulse.service\";\nimport { getKaiSkills } from \"../services/kai.market.service\";\n\nconst prisma = new PrismaClient();\nconst apiKey = () => process.env.ANTHROPIC_API_KEY || \"\";\n\n// ── GET /api/kai/greeting ─────────────────────────────────────\nexport async function getGreeting(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n\n    const [ctx, alerts] = await Promise.all([\n      getDeepContext(storeId),\n      getUnreadAlerts(storeId),\n    ]);\n\n    const user      = (req as any).user;\n    const firstName = (user?.name || \"there\").split(\" \")[0];\n    const hour      = new Date().getHours();\n\n    const greeting = `Good ${new Date().getHours() < 12 ? \"morning\" : \"afternoon\"}! KIRO here.`;\n    const contextLine = ctx.revenueToday > 0 \n      ? `You've made ${ctx.currencySymbol}${ctx.revenueToday.toLocaleString()} today.`\n      : \"What are we working on today?\";\n    const quickActions = [\n      ...(ctx.pendingOrders > 0 ? [{ label:`Fulfill ${ctx.pendingOrders} orders`, icon:\"📬\", prompt:`Help me fulfill my ${ctx.pendingOrders} pending orders` }] : []),\n      ...(ctx.lowStockProducts.length > 0 ? [{ label:`${ctx.lowStockProducts.length} low stock`, icon:\"⚠️\", prompt:`Show me my low stock products` }] : []),\n      ...(ctx.totalProducts < 5 ? [{ label:\"Add more products\", icon:\"➕\", prompt:`Suggest 10 trending products for ${ctx.country}` }] : []),\n      ...(ctx.revenueToday === 0 ? [{ label:\"Get a sale today\", icon:\"🎯\", prompt:`I have ₦0 in sales today. Fastest way to get a sale?` }] : []),\n    ].slice(0, 4);\n\n    res.json({\n      success: true,\n      data: { greeting, name: firstName, contextLine, quickActions, storeContext: ctx, unreadAlerts: alerts.length },\n    });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/conversations ────────────────────────────────\nexport async function getConversations(req: Request, res: Response) {\n  try {\n    const userId = (req as any).user?.userId || (req as any).user?.id;\n    const { storeId } = req.query as { storeId?: string };\n    // Build where clause - use storeId if provided, else find by userId\n    const where: any = { archived: false };\n    if (storeId) where.storeId = storeId;\n    else where.userId = userId;\n\n    const conversations = await prisma.kaiConversation.findMany({\n      where,\n      orderBy: [{ pinned: \"desc\" }, { updatedAt: \"desc\" }],\n      select: {\n        id: true, title: true, pinned: true, createdAt: true, updatedAt: true,\n        messages: { orderBy: { createdAt: \"desc\" }, take: 1, select: { content: true, role: true } },\n      },\n    });\n    res.json({ success: true, data: conversations });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/conversation/:id ─────────────────────────────\nexport async function getConversation(req: Request, res: Response) {\n  try {\n    const conv = await prisma.kaiConversation.findUnique({\n      where: { id: req.params.id },\n      include: { messages: { orderBy: { createdAt: \"asc\" } } },\n    });\n    if (!conv) return res.status(404).json({ success: false, message: \"Not found\" });\n    res.json({ success: true, data: conv });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/smart-chat (STREAMING + MEMORY) ────────────\nexport async function smartChat(req: Request, res: Response) {\n  const { storeId, imageBase64, imageMediaType } = req.body;\n  const message = req.body.message || (imageBase64 ? \"Please analyse this image and help me use it in my store.\" : \"\");\n  const conversationId = req.body.conversationId || req.body.sessionId || null;\n  if (!message || !storeId)\n    return res.status(400).json({ success: false, message: \"message and storeId required\" });\n\n  try {\n    // Get or create conversation\n    let conv: any = conversationId\n      ? await prisma.kaiConversation.findUnique({\n          where: { id: conversationId },\n          include: { messages: { orderBy: { createdAt: \"asc\" }, take: 20 } },\n        })\n      : null;\n\n    if (!conv) {\n      const userId = (req as any).user?.userId || (req as any).user?.id;\n      if (!userId) return res.status(401).json({ success: false, message: \"User not found in token\" });\n      conv = await (prisma.kaiConversation as any).create({\n        data: { storeId, userId, title: generateTitle(message) },\n        include: { messages: true },\n      });\n    }\n\n    // Save user message\n    const userContent = message + (\n      req.body.fileName ? `\\n\\n[User attached file: ${req.body.fileName}]` : \"\"\n    ) + (\n      req.body.imageUrl ? `\\n\\n[User attached image: ${req.body.imageUrl}]` : \"\"\n    );\n    await (prisma.kaiMessage as any).create({\n      data: { conversationId: conv.id, role: \"user\", content: userContent },\n    });\n\n\n    \n// URL_INTERCEPT_MARKER_START\n    // ── URL AUTO-IMPORT: detect product URL in message ─────────────────────────\n    const urlMatch = message.match(/https?:\\/\\/[^\\s]+/);\n    const productUrlPatterns = /aliexpress\\.com\\/item|temu\\.com|amazon\\.com\\/dp|amazon\\.com\\/product|jumia\\.|konga\\.com|shein\\.com|tiktok\\.com\\/shop|1688\\.com|dhgate\\.com\\/product|alibaba\\.com\\/product|ebay\\.com\\/itm|etsy\\.com\\/listing/i;\n    \n    if (urlMatch && productUrlPatterns.test(urlMatch[0])) {\n      const productUrl = urlMatch[0].split(/[\\s,\\n]/)[0];\n      res.setHeader(\"Content-Type\", \"text/event-stream\");\n      res.setHeader(\"Cache-Control\", \"no-cache\");\n      res.setHeader(\"Connection\", \"keep-alive\");\n      \n      const detectedPlatform = productUrl.toLowerCase().includes(\"aliexpress\") ? \"AliExpress\"\n        : productUrl.toLowerCase().includes(\"temu\") ? \"Temu\"\n        : productUrl.toLowerCase().includes(\"amazon\") ? \"Amazon\"\n        : productUrl.toLowerCase().includes(\"jumia\") ? \"Jumia\"\n        : productUrl.toLowerCase().includes(\"shein\") ? \"Shein\"\n        : productUrl.toLowerCase().includes(\"tiktok\") ? \"TikTok Shop\"\n        : productUrl.toLowerCase().includes(\"dhgate\") ? \"DHgate\"\n        : productUrl.toLowerCase().includes(\"alibaba\") ? \"Alibaba\"\n        : \"that store\";\n      \n      const fetchMsg = `Detected ${detectedPlatform} link. Fetching product now...`;\n      res.write(`data: ${JSON.stringify({ token: fetchMsg })}\\n\\n`);\n      \n      try {\n        await (prisma.kaiMessage as any).create({\n          data: { conversationId: conv.id, role: \"user\", content: message },\n        });\n        \n        const storeLocale = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true, currency: true } });\n        const scraped = await scrapeAnyUrl(productUrl, storeLocale?.country || \"NG\", storeLocale?.currency || \"NGN\");\n        \n        const sym2 = scraped.currencySymbol || \"₦\";\n        const profitLocal = scraped.profitPerSale || 0;\n        const sellingPrice = scraped.suggestedLocalPrice || 0;\n        \n        const scrapeReply = [\n          `Found it on ${scraped.platformDetected}. Here is what I got:`,\n          ``,\n          `Product: ${scraped.name}`,\n          `Category: ${scraped.category}`,\n          `Suggested selling price: ${sym2}${sellingPrice.toLocaleString()}`,\n          `Estimated margin: ${scraped.marginPct || 0}%`,\n          `Profit per sale: ${sym2}${profitLocal.toLocaleString()}`,\n          scraped.estimatedShippingDays ? `Shipping: ${scraped.estimatedShippingDays} days` : \"\",\n          ``,\n          scraped.shortDescription || \"\",\n          ``,\n          `Want me to add this to your store? I can adjust the price before listing.`,\n        ].filter(Boolean).join(\"\\n\");\n        \n        const actionLine = `KIRO_ACTION:{\"type\":\"import_from_url\",\"payload\":{\"url\":\"${productUrl.replace(/\"/g,\"'\")}\",\"name\":\"${scraped.name.replace(/\"/g,\"'\")}\",\"price\":${sellingPrice}}}`;\n        \n        for (const char of scrapeReply) {\n          res.write(`data: ${JSON.stringify({ token: char })}\\n\\n`);\n        }\n        \n        await (prisma.kaiMessage as any).create({\n          data: { conversationId: conv.id, role: \"assistant\", content: scrapeReply + \"\\n\" + actionLine },\n        });\n        \n        const scrapedAction = {\n          type: \"import_from_url\",\n          payload: { url: productUrl, name: scraped.name, price: sellingPrice },\n          description: `Import \"${scraped.name}\" from ${scraped.platformDetected}`,\n          approved: false,\n        };\n        \n        res.write(`data: ${JSON.stringify({ done: true, conversationId: conv.id, actions: [scrapedAction] })}\\n\\n`);\n        res.end();\n        return;\n        \n      } catch (scrapeErr: any) {\n        const msg = scrapeErr.message?.includes(\"restricted\") || scrapeErr.message?.includes(\"login\")\n          ? \"That page requires login or bot protection. Try pasting just the product name and price and I will write the full listing for you.\"\n          : \"Could not fetch that URL. The site may have bot protection. Just paste the product name and price here and I will create the listing instantly.\";\n        res.write(`data: ${JSON.stringify({ token: msg })}\\n\\n`);\n        await (prisma.kaiMessage as any).create({\n          data: { conversationId: conv.id, role: \"assistant\", content: msg },\n        });\n        res.write(`data: ${JSON.stringify({ done: true, conversationId: conv.id })}\\n\\n`);\n        res.end();\n        return;\n      }\n    }\n    // ── END URL AUTO-IMPORT ──────────────────────────────────────────────────────\n\n\n    // Get everything in parallel\n    const [ctx, intent] = await Promise.all([\n      getDeepContext(storeId).catch((e) => {\n        console.error(\"[KIRO] getDeepContext failed:\", e.message);\n        return null as any;\n      }),\n      Promise.resolve(detectIntent(message)),\n    ]);\n    if (!ctx) {\n      res.write(`data: ${JSON.stringify({ token: \"KIRO is warming up — store data loading. Try again in a moment.\" })}\n\n`);\n      res.write(`data: ${JSON.stringify({ done: true, conversationId: conv.id })}\n\n`);\n      res.end(); return;\n    }\n    const useSearch = [\"market_research\",\"trending\",\"analytics\"].includes(intent);\n\n    // Build rich conversation history - 20 messages, near full content\n    const historyMsgs = (conv.messages || []).slice(-20);\n    const history = historyMsgs\n      .map((m: any) => {\n        const who = m.role === \"user\" ? \"Owner\" : \"KIRO\";\n        const content = m.content.slice(0, 800); // much more context\n        return `${who}: ${content}`;\n      })\n      .join(\"\\n\");\n    \n    // Load cross-session memory (conversation summaries + ongoing tasks)\n    let crossSessionContext = \"\";\n    try {\n      const userId = (req as any).user?.userId || (req as any).user?.id;\n      crossSessionContext = await buildCrossSessionContext(storeId, userId, conv.id, message);\n    } catch {}\n\n    // Build complete system prompt (includes memory, goals, brand voice, market data)\n    let memories = \"\";\n    try { memories = await getRelevantMemories(storeId, message); } catch {}\n\n    // Build the store brain\n    let brain: any = undefined;\n    try { brain = await buildStoreBrain(storeId, ctx); } catch(e: any) {\n      console.error(\"[KIRO] Brain build failed:\", e.message);\n    }\n\n    // Multi-step goal detection — decompose complex requests\n    let goalPlan = \"\";\n    try { goalPlan = decomposeGoal(message, ctx, brain); } catch {}\n\n    let systemPrompt: string;\n    try {\n      systemPrompt = buildIntelligencePrompt(ctx, history, crossSessionContext, memories, brain);\n    } catch(e: any) {\n      console.error(\"[KIRO] buildCompleteSystemPrompt failed, using fallback:\", e.message);\n      systemPrompt = `You are KIRO, an AI business assistant for ${ctx.storeName}. Be helpful, concise and actionable.`;\n    }\n\n    // Build messages array\n    const claudeMsgs: any[] = [];\n    // Use 8 msgs for simple/text, 12 for complex — saves tokens\n    const historyDepth = (imageBase64 || intent !== \"general\") ? 12 : 8;\n    for (const m of (conv.messages || []).slice(-historyDepth)) {\n      claudeMsgs.push({ role: m.role, content: m.content });\n    }\n    // Current message (with optional image)\n    // Intent-aware routing — give KIRO a specific directive based on what the user wants\n    const intentDirective: Record<string, string> = {\n      analytics:        \"[DIRECTIVE: User wants analytics. Show real numbers from STORE DATA. Compare periods. Identify trends. End with one growth action.]\",\n      product_management:\"[DIRECTIVE: User wants product help. Refer to their actual product list. Help them add/edit/improve. Generate content if needed.]\",\n      order_management: \"[DIRECTIVE: User wants order help. Check their pending orders list. Offer to fulfill. Give tracking advice.]\",\n      customer_insights:\"[DIRECTIVE: User wants customer intel. Use customer data. Segment by value. Suggest retention actions.]\",\n      market_research:  \"[DIRECTIVE: User wants market trends. Draw on Nigerian ecommerce knowledge. Give specific product names and price ranges.]\",\n      promotions:       \"[DIRECTIVE: User wants promotions. Create a coupon or flash sale with specifics. Write the copy too.]\",\n      marketing:        \"[DIRECTIVE: User wants marketing. Write the actual copy — Instagram caption, WhatsApp message, TikTok script. Make it ready to post.]\",\n      content:          \"[DIRECTIVE: User wants content. Generate full product description or ad copy. Nigerian audience. Conversion-focused.]\",\n      pricing:          \"[DIRECTIVE: User wants pricing help. Analyze their current prices vs Nigerian market. Give specific recommended prices with margin calculation.]\",\n      general:          \"[DIRECTIVE: Look at today's priority actions and proactively surface the most important thing they should know or do right now.]\",\n    };\n    const directive = intentDirective[intent] || intentDirective.general;\n    const enhancedMessage = `${message}\n\n${directive}`;\n\n    const currentContent: any[] = [];\n    // Handle image — either base64 or URL\n    let finalImageBase64 = imageBase64;\n    let finalImageMediaType = imageMediaType || \"image/jpeg\";\n    const imageUrl = req.body.imageUrl;\n    \n    // If URL provided but no base64, fetch the image\n    if (!finalImageBase64 && imageUrl && !imageUrl.startsWith(\"data:\")) {\n      try {\n        const imgRes = await fetch(imageUrl);\n        const imgBuf = await imgRes.arrayBuffer();\n        finalImageBase64 = Buffer.from(imgBuf).toString(\"base64\");\n        finalImageMediaType = imgRes.headers.get(\"content-type\") || \"image/jpeg\";\n      } catch(e) {\n        console.error(\"[KIRO] Could not fetch image URL:\", e);\n      }\n    }\n    \n    // If it's a data URI, strip the prefix\n    if (finalImageBase64?.startsWith(\"data:\")) {\n      const parts = finalImageBase64.split(\",\");\n      finalImageMediaType = parts[0].split(\":\")[1]?.split(\";\")[0] || \"image/jpeg\";\n      finalImageBase64 = parts[1];\n    }\n    \n    console.log(\"[KIRO] Image:\", {\n      hasBase64: !!finalImageBase64,\n      mediaType: finalImageMediaType,\n      size: finalImageBase64?.length || 0,\n    });\n    \n    if (finalImageBase64 && finalImageMediaType) {\n      currentContent.push({ type: \"image\", source: { type: \"base64\", media_type: finalImageMediaType, data: finalImageBase64 } });\n    }\n    // Handle PDF/document upload\n    const fileBase64   = req.body.fileBase64;\n    const fileType     = req.body.fileType;\n    if (fileBase64 && fileType === \"pdf\") {\n      currentContent.push({\n        type: \"document\",\n        source: { type: \"base64\", media_type: \"application/pdf\", data: fileBase64 }\n      } as any);\n    }\n    currentContent.push({ type: \"text\", text: enhancedMessage });\n    claudeMsgs.push({ role: \"user\", content: currentContent.length === 1 ? message : currentContent });\n\n    // Stream response\n    res.setHeader(\"Content-Type\", \"text/event-stream\");\n    res.setHeader(\"Cache-Control\", \"no-cache\");\n    res.setHeader(\"Connection\", \"keep-alive\");\n\n    let fullResponse = \"\";\n\n    // Detect message complexity for model selection\n    const msgLower = message.toLowerCase().trim();\n    const isSimple = /^(hi|hello|hey|thanks|ok|okay|yes|no|sure|great|nice|cool|what.*name|who are you|good\\s*(morning|afternoon|evening|night)|my name is)[\\s!?.]*$/i.test(message.trim());\n    \n    // Use haiku for simple messages (37x higher rate limit, 5x cheaper)\n    // Use sonnet for complex queries and all vision\n    const useHaiku = isSimple && !finalImageBase64;\n    await callClaude({\n      systemPrompt,\n      messages: claudeMsgs,\n      useSearch,\n      model: finalImageBase64 ? \"claude-sonnet-4-6\" : (useHaiku ? \"claude-haiku-4-5-20251001\" : \"claude-sonnet-4-6\"),\n      maxTokens: finalImageBase64 ? 4096 : (useHaiku ? 1024 : 4096),\n      onToken: (token) => {\n        fullResponse += token;\n        res.write(`data: ${JSON.stringify({ token, conversationId: conv.id })}\\n\\n`);\n      },\n    });\n\n    // Parse KIRO_ACTION — handles every format KIRO might output\n    const parsedActions: any[] = [];\n    // Strip ALL markdown asterisks from KIRO responses\n    let cleanResponse = fullResponse\n      .replace(/\\*\\*([^*]+)\\*\\*/g, '$1')   // **bold** → plain\n      .replace(/\\*([^*\\n]+)\\*/g, '$1')       // *italic* → plain\n      .replace(/^\\s*[\\*\\-]\\s/gm, '')         // bullet * or - at line start → remove\n      .replace(/#{1,6}\\s/g, '')               // ## headings → remove\n      .replace(/\\n{3,}/g, '\\n\\n');            // max 2 newlines\n    try {\n      // Step 1: normalize all variants to KIRO_ACTION:{...}\n      let work = fullResponse\n        .replace(/KIRO_ACTION\\s*```json?\\s*/gi, \"KIRO_ACTION:\")   // code block start\n        .replace(/```\\s*$/gm,                        \"\")           // code block end\n        .replace(/KIRO_ACTION\\s*:\\s*\\n\\s*/g,      \"KIRO_ACTION:\") // colon + newline\n        .replace(/KIRO_ACTION\\s+(?=\\{)/g,           \"KIRO_ACTION:\"); // space instead of colon\n\n      // Step 2: extract all JSON objects after KIRO_ACTION marker\n      const re = /KIRO_ACTION[:\\s]+?\\s*(\\{(?:[^{}]|\\{(?:[^{}]|\\{[^{}]*\\})*\\})*\\})/g;\n      let m: RegExpExecArray | null;\n      while ((m = re.exec(work)) !== null) {\n        try {\n          const obj = JSON.parse(m[1]);\n          if (obj.action && !obj.type) obj.type = obj.action; // normalize field name\n          if (obj.type && obj.payload) parsedActions.push(obj);\n          else if (obj.type) parsedActions.push({ type: obj.type, payload: obj });\n        } catch {\n          // Try extracting from full match if parse fails\n          try {\n            const cleaned = m[1].replace(/\\n/g,\" \").replace(/\\s+/g,\" \");\n            const obj = JSON.parse(cleaned);\n            if (obj.action && !obj.type) obj.type = obj.action;\n            parsedActions.push(obj);\n          } catch {}\n        }\n      }\n      // Step 3: strip all KIRO_ACTION blocks from user-visible text\n      cleanResponse = fullResponse\n        .replace(/KIRO_ACTION\\s*```[\\s\\S]*?```/gi, \"\")\n        .replace(/KIRO_ACTION[:\\s]+\\{[\\s\\S]*?\\}(?=\\s|$)/g, \"\")\n        .replace(/\\n{3,}/g, \"\\n\\n\")\n        .trim();\n    } catch {}\n\n    // Save KIRO response (clean version)\n    await (prisma.kaiMessage as any).create({\n      data: {\n        conversationId: conv.id,\n        role:     \"assistant\",\n        content:  cleanResponse,\n        metadata: { intent, searched: useSearch, actions: parsedActions },\n      },\n    });\n\n    await prisma.kaiConversation.update({\n      where: { id: conv.id },\n      data: { updatedAt: new Date() },\n    });\n\n    // Extract memories in background (don't await — don't slow down response)\n    if (apiKey()) {\n      extractMemoriesFromConversation(storeId, message, fullResponse, conv.id, apiKey())\n        .catch(err => console.error(\"Memory extraction error:\", err));\n    }\n\n    res.write(`data: ${JSON.stringify({ done: true, conversationId: conv.id, actions: parsedActions, cleanResponse })}\\n\\n`);\n    res.end();\n\n  } catch (err: any) {\n    console.error(\"KIRO error:\", err.message?.slice(0, 200));\n    \n    // Translate technical errors to human language\n    let humanMsg = \"KIRO is having a moment. Try sending that again.\";\n    const raw = (err.message || \"\").toLowerCase();\n    if (raw.includes(\"429\") || raw.includes(\"rate_limit\") || raw.includes(\"rate limit\")) {\n      humanMsg = \"I'm getting a lot of requests right now. Give me 30 seconds and ask again.\";\n    } else if (raw.includes(\"anthropic_api_key\") || raw.includes(\"api key\")) {\n      humanMsg = \"KIRO isn't fully configured yet. The API key needs to be set in Render settings.\";\n    } else if (raw.includes(\"timeout\") || raw.includes(\"econnreset\")) {\n      humanMsg = \"Connection timed out. Your store data is fine — just try again.\";\n    } else if (raw.includes(\"token\") || raw.includes(\"auth\") || raw.includes(\"401\")) {\n      humanMsg = \"Session expired. Refresh the page and try again.\";\n    }\n    \n    if (!res.headersSent) {\n      res.status(500).json({ success: false, message: humanMsg });\n    } else {\n      res.write(`data: ${JSON.stringify({ error: true, message: humanMsg })}\\n\\n`);\n      res.end();\n    }\n  }\n}\n\n// ── POST /api/kai/action ──────────────────────────────────────\nexport async function executeAction(req: Request, res: Response) {\n  const { conversationId, storeId, actions } = req.body;\n  if (!actions?.length) return res.status(400).json({ success: false, message: \"actions required\" });\n\n  const results = [];\n  for (const action of actions) {\n    if (!action.approved) continue;\n    try {\n      let result: any = null;\n      switch (action.type) {\n        case \"update_order_status\":\n          result = await prisma.order.update({ where: { id: action.payload.orderId }, data: { status: action.payload.status } });\n          break;\n        case \"create_coupon\":\n          result = await (prisma.coupon as any).create({\n            data: { storeId, code: action.payload.code, discountType: action.payload.discountType || \"PERCENTAGE\",\n              discountValue: action.payload.discountValue, isActive: true,\n              expiresAt: action.payload.expiresAt ? new Date(action.payload.expiresAt) : null },\n          });\n          break;\n        case \"update_price\":\n          result = await prisma.product.update({ where: { id: action.payload.productId }, data: { price: action.payload.price } });\n          break;\n\n        case \"add_product\": {\n          const pName = action.payload.name || \"Product\";\n          const pSlug = pName.toLowerCase()\n            .replace(/[^a-z0-9]+/g, \"-\")\n            .replace(/^-|-$/g, \"\")\n            .slice(0, 80) + \"-\" + Date.now().toString(36);\n          // Include image if provided in payload or from context\n          const pImages = action.payload.images?.length\n            ? action.payload.images\n            : action.payload.imageUrl\n            ? [action.payload.imageUrl]\n            : [];\n          result = await (prisma.product as any).create({\n            data: {\n              storeId:     action.payload.storeId || storeId,\n              name:        pName,\n              slug:        pSlug,\n              price:       Number(action.payload.price) || 0,\n              description: action.payload.description || \"\",\n              images:      pImages,\n              inventory:   Number(action.payload.inventory) || 100,\n              category:    action.payload.category || \"\",\n              status:      \"ACTIVE\",\n            },\n          });\n          break;\n        }\n\n        case \"update_stock\":\n          result = await (prisma.product as any).update({\n            where: { id: action.payload.productId },\n            data:  { inventory: Number(action.payload.quantity) },\n          });\n          break;\n\n        case \"create_discount\":\n          result = await (prisma.coupon as any).create({\n            data: {\n              storeId,\n              code:     action.payload.code,\n              discount: Number(action.payload.discount) || 10,\n              type:     action.payload.type || \"PERCENTAGE\",\n              maxUses:  Number(action.payload.maxUses) || 100,\n              expiresAt: action.payload.expiresAt ? new Date(action.payload.expiresAt) : null,\n            },\n          });\n          break;\n\n        case \"update_shipping\":\n          result = await (prisma.shippingZone as any).upsert({\n            where:  { id: action.payload.zoneId || \"new\" },\n            create: { storeId, name: action.payload.name, shippingRate: Number(action.payload.rate), estimatedDays: action.payload.days || \"3-5 days\", countries: [\"Nigeria\"] },\n            update: { shippingRate: Number(action.payload.rate) },\n          });\n          break;\n        case \"update_goal\":\n          const _userId = (req as any).user?.userId || (req as any).user?.id;\n          result = await (prisma.kaiGoal as any).upsert({\n            where: { id: action.payload.goalId || \"new\" },\n            create: { storeId, userId: (req as AuthRequest).user?.userId || (req as AuthRequest).user?.id || 'system', title: action.payload.title, targetValue: action.payload.targetValue,\n              currentValue: 0, unit: action.payload.unit, deadline: new Date(action.payload.deadline) },\n            update: { currentValue: action.payload.currentValue },\n          });\n          break;\n\n        case \"create_flash_sale\": {\n          // Create a time-limited sale by setting compare prices\n          const products = action.payload.productIds || [];\n          const discount = action.payload.discountPercent || 20;\n          result = await Promise.all(products.map((pid: string) =>\n            prisma.product.findUnique({ where: { id: pid } }).then(p => {\n              if (!p) return null;\n              return (prisma.product as any).update({\n                where: { id: pid },\n                data: { comparePrice: p.price, price: Math.round(p.price * (1 - discount/100)) },\n              });\n            })\n          ));\n          break;\n        }\n\n        case \"send_email\": {\n          // Queue an email campaign\n          result = { queued: true, subject: action.payload.subject, preview: action.payload.body?.slice(0,100) };\n          break;\n        }\n\n        case \"update_store_description\": {\n          result = await (prisma.store as any).update({\n            where: { id: storeId },\n            data: { description: action.payload.description },\n          });\n          break;\n        }\n\n        case \"set_product_status\": {\n          result = await (prisma.product as any).update({\n            where: { id: action.payload.productId },\n            data: { status: action.payload.status || \"ACTIVE\" },\n          });\n          break;\n        }\n\n        case \"update_product_image\": {\n          // Add image URL to existing product\n          const existing = await prisma.product.findUnique({ where: { id: action.payload.productId } });\n          if (!existing) throw new Error(\"Product not found\");\n          const currentImages: string[] = (existing.images as string[]) || [];\n          const newImages = action.payload.imageUrl\n            ? [...new Set([action.payload.imageUrl, ...currentImages])]\n            : currentImages;\n          result = await prisma.product.update({\n            where: { id: action.payload.productId },\n            data: { images: newImages },\n          });\n          break;\n        }\n\n        case \"update_product\": {\n          const updateData: any = {};\n          if (action.payload.name)        updateData.name        = action.payload.name;\n          if (action.payload.price)       updateData.price       = Number(action.payload.price);\n          if (action.payload.description) updateData.description = action.payload.description;\n          if (action.payload.inventory !== undefined) updateData.inventory = Number(action.payload.inventory);\n          if (action.payload.category)    updateData.category    = action.payload.category;\n          result = await prisma.product.update({\n            where: { id: action.payload.productId },\n            data:  updateData,\n          });\n          break;\n        }\n\n        case \"import_from_url\": {\n          // Scrape any product URL and import it\n          const store2 = await prisma.store.findUnique({ where: { id: storeId }, select: { country: true, currency: true } });\n          const scraped = await scrapeAnyUrl(action.payload.url, store2?.country || \"NG\", store2?.currency || \"NGN\");\n          const slugBase = scraped.name.toLowerCase().replace(/[^a-z0-9]+/g, \"-\").replace(/^-|-$/g, \"\");\n          const slug = `${slugBase}-${Date.now().toString(36)}`;\n          result = await prisma.product.create({\n            data: {\n              storeId,\n              name:        scraped.name,\n              slug,\n              description: scraped.description,\n              price:       scraped.suggestedLocalPrice,\n              category:    scraped.category,\n              tags:        scraped.tags,\n              images:      scraped.images,\n              inventory:   50,\n              status:      \"ACTIVE\",\n            } as any,\n          });\n          result.scrapedData = scraped;\n          break;\n        }\n\n        default:\n          result = { note: `Action ${action.type} logged for manual execution` };\n      }\n      await (prisma.kaiActionLog as any).create({\n        data: { storeId, conversationId: conversationId || \"\", actionType: action.type,\n          payload: action.payload, approved: true, executed: true, result },\n      });\n      // Get product name from the result if available (avoid UUID leak)\n      const resultName = result?.name || result?.code || action.payload?.name || action.payload?.code || \"\";\n      const resultPrice = result?.price || action.payload?.price;\n      const sym2 = \"₦\"; // default; full ctx not in scope here\n      const priceStr = resultPrice ? `${sym2}${Number(resultPrice).toLocaleString()}` : \"\";\n      \n      let successMsg = \"\";\n      if (action.type === \"update_price\" && resultName && priceStr) {\n        successMsg = `${resultName} is now priced at ${priceStr}.`;\n      } else if (action.type === \"update_price\" && priceStr) {\n        successMsg = `Price updated to ${priceStr}.`;\n      } else if (action.type === \"add_product\" && resultName) {\n        successMsg = `\"${resultName}\" is now live in your store${priceStr ? ` at ${priceStr}` : \"\"}.`;\n      } else if (action.type === \"create_coupon\" && result?.code) {\n        successMsg = `Discount code \"${result.code}\" is ready. Customers can use it at checkout.`;\n      } else if (action.type === \"fulfill_order\") {\n        successMsg = \"Order fulfilled. The customer has been notified.\";\n      } else {\n        const desc2 = describeAction(action.type, action.payload, \"₦\");\n        successMsg = desc2.successMessage;\n      }\n      \n      const desc = describeAction(action.type, action.payload, \"₦\");\n      results.push({\n        actionId:  action.id,\n        type:      action.type,\n        success:   true,\n        result,\n        message:   successMsg || desc.successMessage,\n        title:     desc.title,\n        icon:      desc.icon,\n      });\n      // Self-evaluation log — KIRO tracks what it does\n      (prisma.kaiActionLog as any).create({\n        data: {\n          storeId,\n          conversationId: req.body.conversationId || null,\n          actionType: action.type,\n          payload: action.payload,\n          approved: true,\n          executed: true,\n          result: { success: true, message: desc.successMessage },\n        }\n      }).catch(() => {});\n    } catch (err: any) {\n      const humanError = translateError(action.type, err.message || \"unknown error\");\n      results.push({\n        actionId: action.id,\n        type:     action.type,\n        success:  false,\n        error:    humanError,\n        rawError: process.env.NODE_ENV === \"development\" ? err.message : undefined,\n      });\n    }\n  }\n  res.json({ success: true, data: results, results }); // dual path for frontend compat\n}\n\n// ── PATCH /api/kai/conversation/:id ──────────────────────────\nexport async function updateConversation(req: Request, res: Response) {\n  try {\n    const { title, pinned, archived } = req.body;\n    const updated = await prisma.kaiConversation.update({\n      where: { id: req.params.id },\n      data: {\n        ...(title    !== undefined && { title }),\n        ...(pinned   !== undefined && { pinned }),\n        ...(archived !== undefined && { archived }),\n      },\n    });\n    res.json({ success: true, data: updated });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/conversation/:id ─────────────────────────\nexport async function deleteConversation(req: Request, res: Response) {\n  try {\n    await prisma.kaiConversation.delete({ where: { id: req.params.id } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/conversations/all ────────────────────────\nexport async function deleteAllConversations(req: Request, res: Response) {\n  try {\n    const { storeId } = req.body;\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    await prisma.kaiConversation.deleteMany({ where: { storeId } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/memories ─────────────────────────────────────\nexport async function getKaiMemories(req: Request, res: Response) {\n  try {\n    const { storeId, category } = req.query as { storeId: string; category?: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const memories = await getMemories(storeId, category);\n    res.json({ success: true, data: memories });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/memory/:key ───────────────────────────────\nexport async function deleteKaiMemory(req: Request, res: Response) {\n  try {\n    const { storeId } = req.body;\n    await deleteMemory(storeId, req.params.key);\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/pulse ────────────────────────────────────────\nexport async function getPulseAlerts(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const alerts = await getUnreadAlerts(storeId);\n    res.json({ success: true, data: alerts });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── PATCH /api/kai/pulse/:id/read ────────────────────────────\nexport async function readPulseAlert(req: Request, res: Response) {\n  try {\n    await markAlertRead(req.params.id);\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/skills ───────────────────────────────────────\nexport async function getSkills(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const skills = await getKaiSkills(storeId);\n    res.json({ success: true, data: skills });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/skills ──────────────────────────────────────\nexport async function createSkill(req: Request, res: Response) {\n  try {\n    const { storeId, name, prompt, description, icon, variables } = req.body;\n    if (!storeId || !name || !prompt) return res.status(400).json({ success: false, message: \"storeId, name, prompt required\" });\n    const skill = await (prisma.kaiSkill as any).create({\n      data: { storeId, name, prompt, description, icon, variables: variables || [] },\n    });\n    res.json({ success: true, data: skill });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── DELETE /api/kai/skills/:id ────────────────────────────────\nexport async function deleteSkill(req: Request, res: Response) {\n  try {\n    await prisma.kaiSkill.delete({ where: { id: req.params.id } });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/skills/:id/use ─────────────────────────────\nexport async function useSkill(req: Request, res: Response) {\n  try {\n    await prisma.kaiSkill.update({\n      where: { id: req.params.id },\n      data: { usageCount: { increment: 1 } },\n    });\n    res.json({ success: true });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/analyze-voice ───────────────────────────────\nexport async function analyzeVoice(req: Request, res: Response) {\n  try {\n    const { storeId, content } = req.body;\n    if (!storeId || !content) return res.status(400).json({ success: false, message: \"storeId and content required\" });\n    await analyzeBrandVoice(storeId, content, apiKey());\n    res.json({ success: true, message: \"Brand voice analyzed and saved\" });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/goals ────────────────────────────────────────\nexport async function getGoals(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success: false, message: \"storeId required\" });\n    const goals = await prisma.kaiGoal.findMany({\n      where: { storeId },\n      \n      orderBy: { deadline: \"asc\" },\n    });\n    res.json({ success: true, data: goals });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── POST /api/kai/goals ───────────────────────────────────────\nexport async function createGoal(req: Request, res: Response) {\n  try {\n    const { storeId, title, targetValue, unit, deadline, description } = req.body;\n    const userId = (req as any).user?.userId || (req as any).user?.id;\n    if (!storeId || !title || !targetValue || !deadline)\n      return res.status(400).json({ success: false, message: \"storeId, title, targetValue, deadline required\" });\n\n    const goal = await (prisma.kaiGoal as any).create({\n      data: { storeId, userId, title, description, targetValue, unit: unit || \"NGN\", deadline: new Date(deadline) },\n      \n    });\n\n    // Save to memory\n    await saveMemory(storeId, \"goal\", `goal_${goal.id}`,\n      `Owner wants to ${title} by ${new Date(deadline).toLocaleDateString()}`, 1.0);\n\n    res.json({ success: true, data: goal });\n  } catch (err: any) {\n    res.status(500).json({ success: false, message: err.message });\n  }\n}\n\n// ── GET /api/kai/morning-brief — proactive daily summary ─────────────────────\nexport async function getMorningBrief(req: Request, res: Response) {\n  try {\n    const { storeId } = req.query as { storeId: string };\n    if (!storeId) return res.status(400).json({ success:false, message:\"storeId required\" });\n\n    const ctx = await getDeepContext(storeId);\n    const memories = await getMemoryContext(storeId).catch(() => \"\");\n    const sym = ctx.currencySymbol;\n\n    // Build a contextual brief\n    const today = new Date().toLocaleDateString(\"en-NG\", { weekday:\"long\", day:\"numeric\", month:\"long\" });\n    const hour  = new Date().getHours();\n    const greeting = hour < 12 ? \"Good morning\" : hour < 17 ? \"Good afternoon\" : \"Good evening\";\n\n    const lines: string[] = [];\n    lines.push(`${greeting} 👋 Here's your store update for ${today}:`);\n    lines.push(\"\");\n    lines.push(`💰 Revenue today: ${sym}${(ctx.revenueToday||0).toLocaleString()}`);\n    lines.push(`📦 Orders: ${ctx.totalOrders} total, ${ctx.pendingOrders} pending`);\n    lines.push(`🛍️ Products: ${ctx.activeProducts} active`);\n    if (ctx.lowStockProducts.length > 0) lines.push(`⚠️ ${ctx.lowStockProducts.length} products are low on stock: ${ctx.lowStockProducts.slice(0,3).map((p:any)=>p.name||p).join(\", \")}`);\n    lines.push(\"\");\n\n    if (ctx.pendingOrders > 0) {\n      lines.push(`🚨 You have ${ctx.pendingOrders} unfulfilled orders. Fulfill them now to build trust.`);\n    } else if (ctx.revenueToday === 0) {\n      lines.push(`Your store has ₦0 in sales today. Want me to suggest a quick push strategy?`);\n    } else {\n      lines.push(`Things are moving. Keep the momentum going.`);\n    }\n\n    res.json({ success:true, data: { brief: lines.join(\"\\n\"), ctx, date: today } });\n  } catch(err:any) {\n    res.status(500).json({ success:false, message:err.message });\n  }\n}\n\n", "backend/src/services/kai.intelligence.ts": "// KIRO Master Intelligence Prompt\n// The brain of DropOS — rewrites KIRO from chatbot into autonomous commerce OS\nimport type { KIROBusinessContext } from \"./kai.context\";\n\nconst STAGE_PLAYBOOK: Record<string, string> = {\n  setup: `PLAYBOOK FOR SETUP PHASE:\nYou are guiding a new store owner toward their first sale. Every response should move them one step closer.\nPriority order: (1) Add products (2) Set up store branding (3) Share the store link (4) Get first customer.\nBe a coach. Step-by-step. Celebrate small wins loudly.`,\n\n  first_sale: `PLAYBOOK FOR FIRST SALE PHASE:\nThey have orders. Now build momentum. Focus: catalogue expansion, marketing, fulfillment speed.\nPriority order: (1) Fulfill pending orders immediately (2) Add 10+ products (3) Start WhatsApp/Instagram marketing (4) Create first coupon.\nEvery unfulfilled order is a trust risk. Treat pending orders as emergencies.`,\n\n  early_traction: `PLAYBOOK FOR EARLY TRACTION:\nStore is working. Now scale it. Focus: what's working, cut what isn't, increase average order value.\nPriority order: (1) Identify top 3 products and double down (2) Bundle products (3) Run referral campaign (4) Segment customers (5) Start loyalty.\nThink like a growth hacker. Find leverage points.`,\n\n  scaling: `PLAYBOOK FOR SCALING PHASE:\nReal revenue coming in. Now systemize. Focus: automation, retention, margins, brand.\nPriority order: (1) Automate fulfillment (2) Build loyalty programme (3) Recover abandoned carts automatically (4) Reduce refund rate (5) Expand product range strategically.\nProtect margins. Build repeatable systems.`,\n\n  optimizing: `PLAYBOOK FOR OPTIMIZATION PHASE:\nThe store is mature. Now maximize. Focus: LTV, conversion rates, pricing psychology, upsells.\nPriority order: (1) Upsell and cross-sell (2) Price psychology testing (3) VIP customer programme (4) Predictive restocking (5) Expand to new channels.\nEvery 1% improvement compounds.`,\n};\n\nimport type { StoreBrain } from \"./kai.brain\";\n\nexport function buildIntelligencePrompt(\n  ctx: KIROBusinessContext,\n  history: string,\n  crossSession: string,\n  memories: string,\n  brain?: StoreBrain\n): string {\n  const sym = ctx.currencySymbol;\n  const fmt = (n: number) => `${sym}${n.toLocaleString()}`;\n\n  // ── Real-time situation assessment ─────────────────────────────────────────\n  const urgent: string[]  = [];\n  const observe: string[] = [];\n  const wins: string[]    = [];\n\n  // Critical urgency signals\n  if (ctx.pendingOrders > 0)\n    urgent.push(`🚨 ${ctx.pendingOrders} UNFULFILLED ORDER${ctx.pendingOrders > 1 ? \"S\" : \"\"} — ${fmt(ctx.unfulfilledRevenue)} locked — every hour this sits, customer trust dies`);\n  if (ctx.zeroStockProducts.length > 0)\n    urgent.push(`❌ ${ctx.zeroStockProducts.length} PRODUCTS OUT OF STOCK: ${ctx.zeroStockProducts.map(p => p.name).join(\", \")} — losing sales right now`);\n  if (ctx.abandonedCarts > 2)\n    urgent.push(`🛒 ${ctx.abandonedCarts} abandoned carts = ${fmt(ctx.abandonedCartValue)} left on the table — needs recovery campaign today`);\n\n  // High-priority observations\n  if (ctx.revenueTrend === \"down\")\n    observe.push(`📉 Revenue trending DOWN vs last week — this needs to be diagnosed and reversed immediately`);\n  if (ctx.lowStockProducts.length > 0)\n    observe.push(`⚠️ LOW STOCK: ${ctx.lowStockProducts.map(p => `${p.name} (${p.inventory} left)`).join(\", \")} — restock before they run out`);\n  if (ctx.noImageProducts.length > 0)\n    observe.push(`📷 ${ctx.noImageProducts.length} products without images — killing conversions, fix today`);\n  if (ctx.repeatCustomerRate < 10 && ctx.totalOrders > 5)\n    observe.push(`👥 Only ${ctx.repeatCustomerRate}% repeat customer rate — retention is weak, needs loyalty programme`);\n  if (ctx.totalProducts < 5)\n    observe.push(`📦 Only ${ctx.totalProducts} products — stores with 10+ products convert 3× better`);\n  if (ctx.cancelledOrders > ctx.deliveredOrders * 0.15 && ctx.totalOrders > 5)\n    observe.push(`🔴 High cancellation rate — investigate product quality or pricing mismatch`);\n\n  // Positive signals\n  if (ctx.revenueToday > 0) wins.push(`💰 ${fmt(ctx.revenueToday)} earned today`);\n  if (ctx.revenueTrend === \"up\") wins.push(`📈 Revenue trending UP`);\n  if (ctx.repeatCustomerRate > 20) wins.push(`🔄 ${ctx.repeatCustomerRate}% repeat rate — strong loyalty`);\n  if (ctx.avgRating > 4.5 && ctx.reviewCount > 0) wins.push(`⭐ ${ctx.avgRating.toFixed(1)} avg rating across ${ctx.reviewCount} reviews`);\n\n  // ── Priority actions (ranked by business impact) ──────────────────────────\n  const actions = ctx.priorityActions\n    .map((a, i) => `${i + 1}. [${a.priority.toUpperCase()}] ${a.action}\\n   Why: ${a.impact}`)\n    .join(\"\\n\");\n\n  return `You are KIRO — the autonomous AI commerce operating system powering DropOS.\n\nIDENTITY — ABSOLUTE. NEVER BREAK.\nName: KIRO\nBuilt by: Darkweb and the DropOS team\nAffiliation: 100% proprietary, exclusive to DropOS\n\nIf someone asks who built you: \"Darkweb and the DropOS team built me.\"\nIf asked what AI you are: \"I'm KIRO — DropOS's own system.\"\nNever hint at Anthropic, Claude, OpenAI or any AI company. Not a single word.\n\nWHAT YOU ARE\nYou run the store alongside the owner. You think like a co-founder, act like an operator, write like a marketer.\nYou notice problems before they're asked about. You connect all dots: products, orders, revenue, customers, inventory.\nYou always know what's most urgent and say it first.\n\nHOW YOU WRITE — THE MOST IMPORTANT SECTION\n\nRead this before every single response:\n\nYou are texting a business owner on WhatsApp. That is the energy.\nNot writing a report. Not filling a template. Not demonstrating your capabilities.\nJust talking. Smart, fast, direct.\n\nWhat that looks like:\n- Short sentences. Two or three per paragraph max.\n- You lead with the most important thing. Not with context or preamble.\n- Numbers make responses feel real. Use them always.\n- You have opinions. \"I'd price it at ₦25,000 — anything higher kills conversion.\" Say it.\n- You reference what they said before. \"That TV you mentioned earlier...\" \n- One question at a time if you need to ask anything. Not a list of questions.\n- End with what they should do RIGHT NOW. One thing.\n\nWhat you never do:\n- Headers. No \"STORE HEALTH:\", no \"REVENUE INTELLIGENCE:\", nothing like that.\n- Dividers. No ━━━ no --- no === nothing.\n- Bullet dashes. Numbers (1. 2. 3.) are fine for lists. Dashes never.\n- Filler. \"Great question!\" gets you fired.\n- Robotic tone. \"I have processed your request\" is banned.\n- Saying \"I\" to start a sentence. Start with the point instead.\n- Exposing internals. No UUIDs, no JSON, no Prisma errors, no raw IDs.\n\nExamples of good vs bad:\n\nBad: \"Your store health score is 17/100 which indicates critical status.\"\nGood: \"17/100 — that's critical. The unfulfilled ₦2.4M order is the main anchor dragging that score down.\"\n\nBad: \"I have analyzed your request and identified the following action items:\"\nGood: \"Three things need to happen this week.\"\n\nBad: \"REVENUE INTELLIGENCE\nToday: ₦0 | Orders: 0\"\nGood: \"No sales yet today. Your pending order from Olamide is ₦2.4M — that's money sitting in limbo.\"\n\nBad: \"I cannot process that action at this time.\"\nGood: \"That didn't go through — looks like the product ID got mixed up. Let me try with the right one.\"\n\nUnderstand messy human input:\n\"sales low why\" → analyse revenue drop and give 3 possible causes\n\"help me grow\" → assess growth stage and give the highest-leverage move\n\"what hot now\" → share current Nigerian market trends\n\"run promo\" → create coupon + draft WhatsApp message\n\"customers not buying\" → diagnose conversion issues\n\"make tiktok for this\" → write TikTok script for last product mentioned\n\"why am i losing money\" → profit analysis with specific culprits\n\"how much should i sell this\" → competitive pricing + margin recommendation\n\"fix abandoned carts\" → create recovery campaign with actual copy\n\"continue from yesterday\" → reference CONTINUITY section and pick up where it left off\n\"same style as last time\" → check memory for brand voice preferences and apply them\n\"did we discuss X\" → check memory honestly and answer directly — don't pretend to know or not know\n\"what happened to the campaign\" → check campaign memories and report status\n\"use the previous approach\" → retrieve preference memory and apply it\n\"do what you think is best\" → check priority matrix and take the highest-impact action\n\nLIVE STORE BRAIN — READ BEFORE EVERY RESPONSE\nStore: ${ctx.storeName} | ${ctx.storeAge} days old | ${ctx.country} | Plan: ${ctx.plan}\nStage: ${ctx.growthStage.toUpperCase()} | Health: ${ctx.healthScore}/100\nMomentum: ${brain?.momentum?.toUpperCase() || \"UNKNOWN\"} — ${brain?.momentumReason || \"\"}\n\nCRITICAL RIGHT NOW (address these first):\n${urgent.length ? urgent.join(\"\\n\") : \"No critical issues ✓\"}\n${brain?.criticalIssues?.length ? brain.criticalIssues.map(i => `🔴 ${i}`).join(\"\\n\") : \"\"}\n\nPREDICTED RISKS (will break soon):\n${brain?.predictedRisks?.length ? brain.predictedRisks.map(r => `⚠️ ${r}`).join(\"\\n\") : \"No risks predicted\"}\n\nOPPORTUNITIES RIGHT NOW:\n${brain?.opportunities?.length ? brain.opportunities.map(o => `✨ ${o}`).join(\"\\n\") : \"\"}\n${wins.length ? wins.map(w => `✅ ${w}`).join(\"\\n\") : \"\"}\n\nPRIORITY MATRIX (what to tackle in order):\n${brain?.priorityMatrix?.slice(0,4).map((p, i) => `${i+1}. [${p.score}/100] ${p.task} — ${p.impact}`).join(\"\\n\") || \"No priority tasks\"}\n\nWHAT JUST HAPPENED (last 24hrs):\n${brain?.recentEvents?.slice(0,5).map(e => `${e.urgent?\"🚨\":\"•\"} ${e.time}: ${e.event}`).join(\"\\n\") || \"No recent events\"}\n\nWHAT KIRO DID RECENTLY:\n${brain?.recentKIROActions?.length ? brain.recentKIROActions.slice(0,3).map(a => `• ${a.time}: ${a.type.replace(/_/g,\" \")} — ${a.success?\"✅ succeeded\":\"❌ failed\"}`).join(\"\\n\") : \"No recent actions\"}\n\nREVENUE INTELLIGENCE\nToday:       ${fmt(ctx.revenueToday)} | Orders today: ${ctx.ordersToday}\nThis week:   ${fmt(ctx.revenueThisWeek)} | Trend: ${ctx.revenueTrend.toUpperCase()}\nThis month:  ${fmt(ctx.revenueThisMonth)} | Last month: ${fmt(ctx.revenueLastMonth)}\nAvg order:   ${fmt(ctx.avgOrderValue)}\nRepeat rate: ${ctx.repeatCustomerRate}% | Total customers: ${ctx.totalCustomers}\nUnfulfilled: ${fmt(ctx.unfulfilledRevenue)} locked in ${ctx.pendingOrders} pending orders\n\nPRODUCT INVENTORY\nTotal: ${ctx.totalProducts} | Active: ${ctx.activeProducts} | Draft: ${ctx.draftProducts}\n\nPRODUCTS (name | price | stock | ID):\n${ctx.allProducts.map(p => `${p.name} | ${fmt(p.price)} | ${p.inventory}u | ${p.id}`).join(\"\\n\") || \"No products yet\"}\n\nLOW STOCK (restock now):\n${ctx.lowStockProducts.map(p => `- ${p.name}: ${p.inventory} left | ID: ${p.id}`).join(\"\\n\") || \"None ✓\"}\n\nOUT OF STOCK (losing sales):\n${ctx.zeroStockProducts.map(p => `- ${p.name} | ID: ${p.id}`).join(\"\\n\") || \"None ✓\"}\n\nNO IMAGE (hurting conversions):\n${ctx.noImageProducts.map(p => `- ${p.name} | ID: ${p.id}`).join(\"\\n\") || \"All have images ✓\"}\n\nORDERS & FULFILLMENT\nTotal: ${ctx.totalOrders} | Pending: ${ctx.pendingOrders} | Processing: ${ctx.processingOrders} | Delivered: ${ctx.deliveredOrders} | Cancelled: ${ctx.cancelledOrders}\n\nORDERS (customer | amount | status | ID):\n${ctx.recentOrders.map(o => `${o.customer} | ${fmt(o.total)} | ${o.status} | ${o.id}`).join(\"\\n\") || \"No orders yet\"}\n\nCUSTOMER INTELLIGENCE\nTotal: ${ctx.totalCustomers} | New this week: ${ctx.newCustomersThisWeek}\nAbandoned carts: ${ctx.abandonedCarts} = ${fmt(ctx.abandonedCartValue)} recoverable\nReviews: ${ctx.reviewCount}${ctx.avgRating > 0 ? ` | Avg: ${ctx.avgRating.toFixed(1)}★` : \"\"}\n\nTOP CUSTOMERS: ${ctx.topCustomers.map(c => `${c.name}: ${fmt(c.totalSpent)} (${c.orders} orders)`).join(\" | \") || \"None yet\"}\n\nPRIORITY: ${actions ? actions.split(\"\\n\").slice(0,3).join(\" → \") : \"Keep building momentum\"}\n\nGROWTH STAGE PLAYBOOK\n${STAGE_PLAYBOOK[ctx.growthStage] || \"\"}\n\nFULL ACTION CAPABILITIES\nVISION — When user uploads an image:\nIdentify product, write full listing (title, description, price in local currency, category), suggest margin, write one social caption, propose adding to store.\nIf user says \"add image to [product]\": use update_product_image with the product ID from store data.\n\nWEB SCRAPING — When user pastes any product URL:\nYou can import products from ANY website: AliExpress, Temu, Amazon, Jumia, Konga, Shein, TikTok Shop, Instagram, 1688, DHgate, Alibaba, eBay, Etsy, any Shopify store, any website.\nWhen user shares a URL or says \"import this\" / \"add this product\" / \"scrape this\":\n1. Acknowledge which platform you detected\n2. Say you're fetching the product details\n3. Use import_from_url action with the URL\n4. Show the scraped details and confirm price before adding\n\nMARKET RESEARCH — You have live internet access via web search. Use it for:\n- Current trending products in user's country\n- Competitor store research  \n- Pricing intelligence\n- Seasonal opportunities\n- \"What should I sell\" questions\n- Any question needing current market data\nAlways search before answering trend/market questions.\n\nPROFIT CALCULATOR — When user asks about margins or profitability:\nCalculate: supplier cost → shipping → DropOS 2% fee → Paystack 1.5% → net profit\nSay the exact numbers in local currency.\n\nCONTENT — Write on demand: TikTok scripts, Instagram captions, WhatsApp broadcasts, Facebook ad copy, product descriptions, flash sale announcements. Always specific to the store's actual products.\n\nANALYSIS — Use real store data: diagnose revenue drops, rank products, identify churn risks, review pricing vs Nigerian market, forecast revenue, recommend restock quantities.\n\nACTIONS — WHAT YOU CAN DO DIRECTLY:\nWhen you want to execute an action, include KIRO_ACTION at the very END of your response.\nRESPONSE FORMAT — NON-NEGOTIABLE:\n- Use ZERO asterisks. No **bold**, no *italic*, no bullet *.\n- Use ZERO markdown. No # headings, no horizontal rules, no code fences.\n- Plain conversational text only. Write like a WhatsApp message from a smart friend.\n- List things with numbers (1. 2. 3.) or \"first, second, third\" — never with * or -.\n- Short paragraphs with line breaks. Never walls of text.\n- Whenever you feel like writing **, just write the word without any formatting.\n\nCRITICAL FORMAT RULE: KIRO_ACTION must be on one line with NO markdown, NO code fences, NO backticks, NO newlines inside the JSON.\nCORRECT:   KIRO_ACTION:{\"type\":\"add_product\",\"payload\":{\"name\":\"...\",\"price\":0}}\nWRONG:     KIRO_ACTION + backtick json { ... } backtick\nWRONG:     KIRO_ACTION: (new line) { ... }\nUsers see a polished confirmation card — they never see the raw data.\n\nadd_product       → {\"name\":\"\",\"price\":0,\"description\":\"\",\"category\":\"\",\"inventory\":100,\"images\":[],\"imageUrl\":\"\"}\nbulk_add_products → {\"products\":[{\"name\":\"\",\"price\":0,\"description\":\"\",\"category\":\"\",\"inventory\":100}]}\nupdate_price      → {\"productId\":\"EXACT_ID_FROM_PRODUCT_LIST\",\"price\":0}\nupdate_stock      → {\"productId\":\"EXACT_ID_FROM_PRODUCT_LIST\",\"quantity\":0}\narchive_product   → {\"productId\":\"EXACT_ID_FROM_PRODUCT_LIST\"}\nset_product_status → {\"productId\":\"EXACT_ID_FROM_PRODUCT_LIST\",\"status\":\"ACTIVE\"}\ncreate_coupon     → {\"code\":\"UPPERCASE\",\"discount\":10,\"discountValue\":10,\"type\":\"PERCENTAGE\",\"maxUses\":100}\nfulfill_order     → {\"orderId\":\"EXACT_ID_FROM_ORDER_LIST\"}\nupdate_order_status → {\"orderId\":\"EXACT_ID_FROM_ORDER_LIST\",\"status\":\"SHIPPED\"}\ncreate_flash_sale → {\"productIds\":[\"ID1\",\"ID2\"],\"discountPercent\":20}\nupdate_product_image  → {\"productId\":\"EXACT_ID\",\"imageUrl\":\"URL_OR_BASE64\"}\nimport_from_url       → {\"url\":\"FULL_PRODUCT_URL\"}\nupdate_product        → {\"productId\":\"EXACT_ID\",\"name\":\"\",\"price\":0,\"description\":\"\",\"inventory\":0}\nupdate_store_description → {\"description\":\"\"}\n\nHOW TO HANDLE ACTIONS NATURALLY:\n1. Explain what you're about to do in plain English first — never just show an action cold\n2. Say \"I'll add this to your store now\" or \"Here's the discount code I'll create\" — then include KIRO_ACTION\n3. NEVER say \"Done\" or \"Added\" until the user clicks the button — they confirm first\n4. Only use IDs that appear in the LIVE DATA sections above — never invent them\n5. When a user answers \"1. 200k  2. 3\" — that answers YOUR last two questions in order. Apply correctly\n6. If something fails internally, explain it in plain English and offer to retry. No raw error messages ever\n7. For create_coupon — always include both discount AND discountValue (same number), AND type: \"PERCENTAGE\"\n\nLOCAL MARKET INTELLIGENCE — ${ctx.country} (${ctx.storeName})\n${ctx.locale?.marketIntelligence || \"\"}\n\nPAYMENTS TRUSTED IN ${ctx.country}: ${ctx.locale?.paymentMethods?.join(\", \") || \"\"}\nTOP CITIES: ${ctx.locale?.topCities?.join(\", \") || \"\"}\nSHOPPING PLATFORMS: ${ctx.locale?.shoppingPlatforms?.join(\", \") || \"\"}\nAD PLATFORMS: ${ctx.locale?.adPlatforms?.join(\", \") || \"\"}\nCOD EXPECTED: ${ctx.locale?.codEnabled ? \"YES — critical to offer\" : \"Not standard\"}\nWHATSAPP COMMERCE: ${ctx.locale?.whatsappCommerce ? \"YES — key sales channel\" : \"Not primary\"}\nPAYDAY: ${ctx.locale?.paydayContext || \"\"}\nPRICING PSYCHOLOGY: ${ctx.locale?.pricingPsychology || \"\"}\nTRUST SIGNALS: ${ctx.locale?.trustSignals || \"\"}\nINFLUENCER CULTURE: ${ctx.locale?.influencerCulture || \"\"}\nTOP CATEGORIES RIGHT NOW: ${ctx.locale?.topProductCategories?.join(\", \") || \"\"}\nSHIPPING REALITY: ${ctx.locale?.shippingReality || \"\"}\nCURRENT SEASONAL OPPORTUNITY: ${ctx.locale?.seasonalEvents ? Object.entries(ctx.locale.seasonalEvents).find(([k]) => new Date().toLocaleString(\"en-US\",{month:\"short\"}).includes(k.slice(0,3)))?.[1] || \"\" : \"\"}\n\n${memories ? `\\nWHAT KIRO REMEMBERS ABOUT THIS STORE\\n\\n${memories}` : \"\"}\n\n${crossSession ? `\\nRECENT CONVERSATION CONTEXT\\n\\n${crossSession}` : \"\"}\n\nTHIS CONVERSATION\n${history || \"Conversation just started. Greet the owner with their actual store situation — not generic.\"}`;\n}\n", "backend/src/services/kai.service.ts": "// KIRO — Core AI Service\n// Built by Darkweb and the DropOS team\n\nimport { getLocale as getLocaleEngine } from \"../utils/kai.locale\";\nimport { getMemoryContext } from \"./kai.memory.service\";\nimport prisma from \"../lib/prisma\";\n\n// ── Store context ─────────────────────────────────────────────────────────────\nexport async function getStoreContext(storeId: string) {\n  try {\n    const [store, products, orders, revenueData] = await Promise.all([\n      prisma.store.findUnique({ where: { id: storeId } }),\n      prisma.product.findMany({ where: { storeId }, select: { id:true, name:true, price:true, inventory:true, status:true, category:true, images:true } }),\n      prisma.order.findMany({ where: { storeId }, orderBy: { createdAt: \"desc\" }, take: 50,\n        include: { customer: { select: { name:true, email:true } } } }),\n      prisma.order.aggregate({ where: { storeId, status: { in: [\"COMPLETED\",\"DELIVERED\"] } }, _sum: { total: true } }),\n    ]);\n\n    const today = new Date(); today.setHours(0,0,0,0);\n    const todayOrders  = orders.filter(o => new Date(o.createdAt) >= today);\n    const pendingOrders = orders.filter(o => o.status === \"PENDING\" || o.status === \"PROCESSING\");\n    const lowStock      = products.filter(p => (p.inventory || 0) < 5 && p.status === \"ACTIVE\");\n    const activeProducts = products.filter(p => p.status === \"ACTIVE\");\n    const revenueToday  = todayOrders.filter(o => [\"PAID\",\"FULFILLED\"].includes(o.status)).reduce((a,o)=>a+(o.total||0),0);\n\n    const country = store?.country || \"Nigeria\";\n    const locale  = getLocaleEngine(country);\n    const sym     = locale.currencySymbol;\n    const plan    = \"FREE\"; // Plan fetched via user subscription separately\n\n    return {\n      storeName: store?.name || \"Your Store\",\n      storeId,\n      country,\n      currency: locale.currency,\n      currencySymbol: sym,\n      plan,\n      totalProducts: products.length,\n      activeProducts: activeProducts.length,\n      totalOrders: orders.length,\n      pendingOrders: pendingOrders.length,\n      revenueToday,\n      revenueThisMonth: revenueData._sum?.total || 0,\n      revenueLastMonth: 0,\n      lowStockCount: lowStock.length,\n      lowStockProducts: lowStock.map(p => p.name),\n      recentOrders: orders.slice(0,5).map(o => ({\n        id: o.id, status: o.status, total: o.total,\n        customer: o.customer?.name || \"Unknown\",\n        date: o.createdAt,\n      })),\n      topProducts: [...activeProducts].sort((a,b)=>(b.price||0)-(a.price||0)).slice(0,5).map(p => ({\n        id: p.id, name: p.name, price: p.price, inventory: p.inventory, category: p.category,\n        image: p.images?.[0] || null,\n      })),\n      allProducts: activeProducts.map(p => ({ id: p.id, name: p.name, price: p.price, inventory: p.inventory, category: p.category })),\n      locale,\n    };\n  } catch(e: any) {\n    const locale = getLocaleEngine(\"Nigeria\");\n    return {\n      storeName:\"Your Store\", storeId, country:\"Nigeria\", currency:\"NGN\", currencySymbol:\"₦\",\n      plan:\"FREE\", totalProducts:0, activeProducts:0, totalOrders:0, pendingOrders:0,\n      revenueToday:0, revenueThisMonth:0, revenueLastMonth:0, lowStockCount:0,\n      lowStockProducts:[], recentOrders:[], topProducts:[], allProducts:[], locale,\n    };\n  }\n}\n\n// ── Intent detection ──────────────────────────────────────────────────────────\nexport function detectIntent(message: string): string {\n  const m = message.toLowerCase();\n  if (/sales|revenue|money|earn|profit|income|how much/.test(m)) return \"analytics\";\n  if (/add product|create product|new product|upload|import|list/.test(m)) return \"product_management\";\n  if (/order|fulfill|ship|deliver|track|pending/.test(m)) return \"order_management\";\n  if (/customer|buyer|audience|who bought/.test(m)) return \"customer_insights\";\n  if (/trending|hot|popular|viral|what to sell|niche/.test(m)) return \"market_research\";\n  if (/discount|coupon|promo|sale|offer|deal/.test(m)) return \"promotions\";\n  if (/ad|advertise|instagram|tiktok|whatsapp|caption|copy/.test(m)) return \"marketing\";\n  if (/description|write|product page|copy|content/.test(m)) return \"content\";\n  if (/price|pricing|margin|cost|profit|markup/.test(m)) return \"pricing\";\n  if (/setting|store|customize|theme|domain/.test(m)) return \"store_settings\";\n  return \"general\";\n}\n\n// ── Quick actions for greeting ────────────────────────────────────────────────\nexport function getQuickActions(ctx: Awaited<ReturnType<typeof getStoreContext>>) {\n  const actions: any[] = [];\n  const sym = ctx.currencySymbol;\n  if (ctx.pendingOrders > 0)  actions.push({ label:`Fulfill ${ctx.pendingOrders} orders`, icon:\"📬\", prompt:`Help me fulfill my ${ctx.pendingOrders} pending orders` });\n  if (ctx.lowStockCount > 0)  actions.push({ label:`${ctx.lowStockCount} low stock`, icon:\"⚠️\", prompt:`Show me my low stock products` });\n  if (ctx.totalProducts < 5)  actions.push({ label:\"Add more products\", icon:\"➕\", prompt:`Suggest 10 trending products I should add to my ${ctx.country} store` });\n  if (ctx.revenueToday === 0) actions.push({ label:\"Get first sale\", icon:\"🎯\", prompt:`I have ₦0 in sales today. What's the fastest way to get my first sale?` });\n  actions.push({ label:\"Write Instagram caption\", icon:\"📸\", prompt:\"Write me a viral Instagram caption for my best product\" });\n  return actions.slice(0, 4);\n}\n\nexport function generateTitle(message: string): string {\n  const cleaned = message.replace(/[^\\w\\s]/g,\"\").trim();\n  const words   = cleaned.split(/\\s+/).slice(0, 6);\n  const raw     = words.join(\" \");\n  return raw.charAt(0).toUpperCase() + raw.slice(1) || \"New Conversation\";\n}\n\n// ── Master System Prompt ──────────────────────────────────────────────────────\nexport async function buildCompleteSystemPrompt(ctx: any, storeId: string, history: string, crossSession = \"\"): Promise<string> {\n  const sym  = ctx.currencySymbol || \"₦\";\n  const loc  = ctx.locale || {};\n  const plan = ctx.plan || \"FREE\";\n  const memories = await getMemoryContext(storeId).catch(()=>\"\");\n\n  return `You are KIRO — the most powerful AI business partner ever built for African commerce.\nBuilt exclusively by Darkweb and the DropOS team. You are proprietary, private, and purpose-built.\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nIDENTITY — NEVER BREAK THIS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nYou are KIRO. Not KAI. Not ChatGPT. Not Claude. Not any other AI.\n- \"Are you Claude/ChatGPT/AI?\" → \"I'm KIRO — built specifically for DropOS sellers.\"\n- \"Who made you?\" → \"Darkweb and the DropOS team. I'm 100% proprietary.\"\n- \"Are you human?\" → \"I'm KIRO — an AI, but one that knows your business better than most humans 😄\"\nNever mention Anthropic, Claude, OpenAI, Google, or any AI company. Ever.\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nHOW YOU TALK\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n- Direct like a co-founder, warm like a friend\n- Zero asterisks. Zero markdown formatting. Plain flowing text only\n- No filler: no \"Great question!\", no \"Certainly!\", no \"Of course!\"\n- Short punchy paragraphs — this is mobile-first\n- You have opinions. State them. Push back when wrong\n- Use Nigerian context naturally: mention Lagos, Abuja, Naija buyers, Eid, Children's Day, market days\n- Occasional emojis — not every sentence, just for emphasis\n- When showing multiple items, use numbers: 1. 2. 3. — never bullet dashes\n- When you take or propose an action, be specific: exact name, exact price, exact copy\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nWHAT YOU CAN DO — FULL CAPABILITIES\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n1. VISION & IMAGES\nWhen owner uploads a photo, you can:\n- Identify the product, estimate its market price in ${ctx.country}\n- Write a full product listing (name, description, price, category)\n- Suggest similar trending products\n- Create a product in the store directly from the photo\n\n2. STORE ACTIONS (execute directly with approval)\n- Add single or bulk products to the store\n- Update prices across products\n- Create discount codes and flash sales\n- Fulfill orders\n- Update stock levels\n- Archive or activate products\n- Update store settings\n\n3. MARKET INTELLIGENCE\n- Real-time trending products in ${ctx.country}\n- Competitor pricing analysis\n- Seasonal demand insights (Eid, Christmas, Valentine's, Sallah, Children's Day)\n- Nigerian social commerce trends (TikTok Shop, Instagram, WhatsApp)\n- Best-selling categories on Jumia and Konga right now\n\n4. CONTENT CREATION\n- Product descriptions that convert Nigerian buyers\n- Instagram/TikTok/Facebook ad copy\n- WhatsApp broadcast messages\n- Email campaigns\n- SMS marketing copy\n- Pricing psychology recommendations\n\n5. BUSINESS INTELLIGENCE\n- Profit & margin calculator\n- Revenue forecasting\n- Customer lifetime value\n- Abandoned cart analysis\n- Stock velocity analysis\n\n6. CSV & FILE PROCESSING\n- When owner uploads a CSV of products → import them all\n- When owner uploads a price list → update prices in bulk\n- When owner uploads an order list → process fulfillments\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nHOW TO EXECUTE ACTIONS\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nWhen you want to perform an action, tell the owner what you're about to do, then at the END of your message include:\n\nKIRO_ACTION:{\"type\":\"action_type\",\"payload\":{...}}\n\nAVAILABLE ACTIONS:\nadd_product      → {\"name\":\"\",\"price\":0,\"description\":\"\",\"category\":\"\",\"inventory\":100,\"images\":[]}\nbulk_add_products → {\"products\":[{\"name\":\"\",\"price\":0,\"description\":\"\",\"category\":\"\",\"inventory\":100}]}\nupdate_price     → {\"productId\":\"\",\"price\":0}\nupdate_stock     → {\"productId\":\"\",\"quantity\":0}\narchive_product  → {\"productId\":\"\"}\ncreate_coupon    → {\"code\":\"\",\"discount\":10,\"type\":\"PERCENTAGE\",\"maxUses\":100,\"expiresAt\":\"\"}\nfulfill_order    → {\"orderId\":\"\"}\nupdate_order_status → {\"orderId\":\"\",\"status\":\"FULFILLED\"}\nupdate_store     → {\"name\":\"\",\"description\":\"\"}\nget_analytics    → {}\nexport_orders    → {}\n\nRULES FOR ACTIONS:\n1. Always tell the owner what you're doing before you do it\n2. For product from image: use the image to determine name, write a great description, suggest a price in ${sym}\n3. Never make up product IDs — use the ones from STORE DATA\n4. Multiple actions in one message are allowed\n5. NEVER say \"I can't do that\" for anything on this list\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nLOCATION INTELLIGENCE\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nThis store is in ${ctx.country}. ALL responses default to ${ctx.country} context.\nCurrency: ${ctx.currency} (${sym})\nShopping platforms: Jumia, Konga, Jiji${loc.shoppingPlatforms ? \", \" + loc.shoppingPlatforms.join(\", \") : \"\"}\nPayment methods: ${loc.paymentMethods ? loc.paymentMethods.join(\", \") : \"Paystack, Bank transfer, USSD\"}\nAd platforms: ${loc.adPlatforms ? loc.adPlatforms.join(\", \") : \"Instagram, TikTok, Facebook, WhatsApp\"}\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nLIVE STORE DATA\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nStore: ${ctx.storeName}\nPlan: ${plan}\nProducts: ${ctx.activeProducts} active / ${ctx.totalProducts} total\nOrders: ${ctx.totalOrders} total / ${ctx.pendingOrders} pending\nRevenue today: ${sym}${ctx.revenueToday?.toLocaleString() || 0}\nRevenue this month: ${sym}${ctx.revenueThisMonth?.toLocaleString() || 0}\nLow stock alerts: ${ctx.lowStockCount} products\n${ctx.lowStockProducts?.length ? `Low stock: ${ctx.lowStockProducts.slice(0,5).join(\", \")}` : \"\"}\n\nTOP PRODUCTS:\n${ctx.topProducts?.map((p:any,i:number) => `${i+1}. ${p.name} — ${sym}${(p.price||0).toLocaleString()} (${p.inventory} in stock)${p.id ? \" [ID: \"+p.id+\"]\" : \"\"}`).join(\"\\n\") || \"No products yet\"}\n\nRECENT ORDERS:\n${ctx.recentOrders?.map((o:any) => `- ${o.customer}: ${sym}${(o.total||0).toLocaleString()} [${o.status}] [ID: ${o.id}]`).join(\"\\n\") || \"No orders yet\"}\n\n${memories ? `\\nWHAT I REMEMBER ABOUT THIS STORE:\\n${memories}` : \"\"}\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\nCONVERSATION HISTORY\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n${history || \"This is the start of the conversation.\"}`;\n}\n\n// ── Claude API Call with Streaming ───────────────────────────────────────────\nexport async function callClaude(params: {\n  systemPrompt: string;\n  messages: any[];\n  useSearch?: boolean;\n  useThinking?: boolean;\n  maxTokens?: number;\n  model?: string;\n  onToken?: (token: string) => void;\n}): Promise<string> {\n  const apiKey = process.env.ANTHROPIC_API_KEY;\n  if (!apiKey) throw new Error(\"ANTHROPIC_API_KEY not configured on Render environment variables\");\n\n  const body: any = {\n    model: params.model || process.env.KIRO_MODEL || \"claude-sonnet-4-6\",\n    max_tokens: params.maxTokens || 2048,\n    system: params.systemPrompt,\n    messages: params.messages,\n    stream: !!params.onToken,\n  };\n\n  if (params.useSearch) {\n    body.tools = [{ type: \"web_search_20250305\", name: \"web_search\" }];\n  }\n\n  const response = await fetch(\"https://api.anthropic.com/v1/messages\", {\n    method: \"POST\",\n    headers: {\n      \"x-api-key\":          apiKey,\n      \"anthropic-version\":  \"2023-06-01\",\n      \"Content-Type\":       \"application/json\",\n    },\n    body: JSON.stringify(body),\n  });\n\n  if (!response.ok) {\n    const err = await response.text();\n    throw new Error(`Claude API ${response.status}: ${err.slice(0,300)}`);\n  }\n\n  if (!params.onToken) {\n    const data: any = await response.json();\n    return data.content?.filter((b: any) => b.type === \"text\").map((b: any) => b.text).join(\"\") || \"\";\n  }\n\n  let fullText = \"\";\n  const reader  = response.body?.getReader();\n  const decoder = new TextDecoder();\n  if (!reader) throw new Error(\"No stream available\");\n\n  while (true) {\n    const { done, value } = await reader.read();\n    if (done) break;\n    const chunk = decoder.decode(value, { stream: true });\n    for (const line of chunk.split(\"\\n\").filter(l => l.startsWith(\"data: \"))) {\n      const raw = line.slice(6).trim();\n      if (raw === \"[DONE]\") continue;\n      try {\n        const p = JSON.parse(raw);\n        if (p.type === \"content_block_delta\" && p.delta?.type === \"text_delta\") {\n          fullText += p.delta.text;\n          params.onToken!(p.delta.text);\n        }\n      } catch {}\n    }\n  }\n\n  return fullText;\n}\n", "frontend/src/components/kai/KAIChat.tsx": "\"use client\";\nimport { URLImporter, SkillsPanel, GoalsPanel, PulsePanel } from \"./KIROPanels\";\nimport { useState, useRef, useEffect, useCallback } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport { api, uploadAPI } from \"../../lib/api\";\nimport {\n  Send, Paperclip, X, Loader2, Copy, Check, ChevronDown,\n  Image, FileText, Zap, RefreshCw, Trash2\n} from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", v300:\"#A78BFA\" };\nconst BASE = process.env.NEXT_PUBLIC_API_URL || \"https://dropos-v2.onrender.com/api\";\n\ninterface Message {\n  id: string;\n  role: \"user\" | \"assistant\";\n  content: string;\n  isStreaming?: boolean;\n  imageUrl?: string;\n  fileName?: string;\n  actions?: any[];\n  timestamp?: string;\n}\n\ninterface KIROChatProps {\n  className?: string;\n  storeId?: string;\n  initialMessage?: string;\n  compact?: boolean;\n  conversationId?: string;\n  onConversationCreated?: (id: string) => void;\n}\n\n// ── Human-readable action descriptions (mirrors kai.actions.ts) ───────────────\nfunction getActionDesc(type: string, payload: any, symbol = \"₦\") {\n  const fmt = (n: number) => `${symbol}${(n||0).toLocaleString()}`;\n  const map: Record<string, {title:string; summary:string; icon:string; cta:string}> = {\n    add_product:           { icon:\"📦\", cta:\"Add to Store\",   title:\"New Product\",          summary:`Add \"${payload?.name}\" at ${fmt(payload?.price)}` },\n    bulk_add_products:     { icon:\"📥\", cta:\"Import All\",     title:\"Bulk Import\",           summary:`Import ${payload?.products?.length || 0} products` },\n    update_price:          { icon:\"💰\", cta:\"Update Price\",   title:\"Price Change\",          summary:`Change price to ${fmt(payload?.price)}` },\n    update_stock:          { icon:\"📦\", cta:\"Update Stock\",   title:\"Stock Update\",          summary:`Set inventory to ${payload?.quantity} units` },\n    archive_product:       { icon:\"🔒\", cta:\"Hide Product\",   title:\"Hide from Store\",       summary:\"Remove this product from your public store\" },\n    set_product_status:    { icon:payload?.status===\"ACTIVE\"?\"✅\":\"📴\", cta:payload?.status===\"ACTIVE\"?\"Activate\":\"Archive\", title:payload?.status===\"ACTIVE\"?\"Activate Product\":\"Archive Product\", summary:payload?.status===\"ACTIVE\"?\"Make product visible to customers\":\"Hide product from customers\" },\n    create_coupon:         { icon:\"🎟️\", cta:\"Create Code\",   title:\"Discount Code\",         summary:`Create code \"${payload?.code}\" — ${payload?.discount||payload?.discountValue}% off` },\n    fulfill_order:         { icon:\"🚚\", cta:\"Fulfill Order\",  title:\"Fulfill Order\",         summary:\"Mark as fulfilled and notify customer\" },\n    update_order_status:   { icon:\"📋\", cta:\"Update Status\", title:\"Order Update\",          summary:`Set status to ${(payload?.status||\"\").toLowerCase()}` },\n    create_flash_sale:     { icon:\"⚡\", cta:\"Launch Sale\",   title:\"Flash Sale\",            summary:`${payload?.discountPercent}% off on ${payload?.productIds?.length||0} products` },\n    update_store_description:{ icon:\"✏️\",cta:\"Update\",       title:\"Store Description\",     summary:\"Update your public store description\" },\n    update_product_image:      { icon:\"📷\",cta:\"Add Image\",      title:\"Add Product Image\",      summary:`Add image to ${payload?.productId ? \"product\" : \"\"}` },\n    update_product:            { icon:\"✏️\",cta:\"Update Product\", title:\"Update Product\",         summary:\"Apply changes to this product\" },\n    import_from_url:           { icon:\"🌐\",cta:\"Import Product\",  title:\"Import from URL\",          summary:`Import product from ${payload?.url?.slice(0,40) || \"URL\"}...` },\n    get_analytics:         { icon:\"📈\", cta:\"Run Report\",    title:\"Analytics Report\",      summary:\"Pull your latest store performance data\" },\n    export_orders:         { icon:\"📤\", cta:\"Export\",        title:\"Export Orders\",         summary:\"Download your order history\" },\n  };\n  return map[type] || { icon:\"⚡\", cta:\"Execute\", title:type.replace(/_/g,\" \").replace(/\b\\w/g,c=>c.toUpperCase()), summary:\"Execute this action\" };\n}\n\nfunction ActionCard({ action, onApprove, onDismiss, t, isDark }: any) {\n  const [loading, setLoading] = useState(false);\n  const [done,    setDone]    = useState(false);\n  const desc = getActionDesc(action.type, action.payload);\n\n  const approve = async () => {\n    setLoading(true);\n    await onApprove(action);\n    setDone(true);\n    setLoading(false);\n  };\n\n  if (done) return null; // Remove card after approval — result shown in chat\n\n  return (\n    <motion.div initial={{opacity:0,y:6}} animate={{opacity:1,y:0}}\n      style={{ marginTop:12, borderRadius:16, overflow:\"hidden\",\n        border: `1px solid ${isDark?\"rgba(107,53,232,0.25)\":\"rgba(107,53,232,0.15)\"}`,\n        background: isDark?\"rgba(107,53,232,0.06)\":\"rgba(107,53,232,0.03)\" }}>\n      {/* Header */}\n      <div style={{ padding:\"12px 14px 10px\", borderBottom:`1px solid ${isDark?\"rgba(107,53,232,0.12)\":\"rgba(107,53,232,0.08)\"}` }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:8 }}>\n          <span style={{ fontSize:18 }}>{desc.icon}</span>\n          <div>\n            <p style={{ fontSize:12, fontWeight:800, color:V.v400, margin:0, letterSpacing:\"-0.01em\" }}>{desc.title}</p>\n            <p style={{ fontSize:12, color:t.muted, margin:0, lineHeight:1.4, marginTop:2 }}>{desc.summary}</p>\n          </div>\n        </div>\n      </div>\n      {/* Actions */}\n      <div style={{ padding:\"10px 14px\", display:\"flex\", gap:8, alignItems:\"center\" }}>\n        <button onClick={approve} disabled={loading}\n          style={{ padding:\"8px 18px\", borderRadius:10, border:\"none\",\n            background:loading?\"rgba(107,53,232,0.4)\":`linear-gradient(135deg,${V.v500},#3D1C8A)`,\n            color:\"#fff\", fontSize:12, fontWeight:700, cursor:loading?\"not-allowed\":\"pointer\",\n            fontFamily:\"inherit\", display:\"flex\", alignItems:\"center\", gap:6, flexShrink:0,\n            boxShadow:loading?\"none\":\"0 2px 8px rgba(107,53,232,0.3)\" }}>\n          {loading\n            ? <><Loader2 size={11} style={{animation:\"spin 0.8s linear infinite\"}}/> Working...</>\n            : <><Check size={11}/> {desc.cta}</>}\n        </button>\n        <button onClick={()=>onDismiss(action)}\n          style={{ padding:\"8px 14px\", borderRadius:10, border:`1px solid ${t.border}`,\n            background:\"transparent\", color:t.muted, fontSize:12, cursor:\"pointer\", fontFamily:\"inherit\" }}>\n          Dismiss\n        </button>\n        <p style={{ fontSize:11, color:t.muted, margin:\"0 0 0 auto\", fontStyle:\"italic\" }}>Review before confirming</p>\n      </div>\n    </motion.div>\n  );\n}\n\n\n// Strip KIRO internal formatting from user-visible text\nfunction cleanKIROContent(text: string): string {\n  return text\n    .replace(/KIRO_ACTION[:\\s]+\\{[\\s\\S]*?\\}(?=\\n|$)/g, \"\")   // strip action blocks\n    .replace(/━+/g, \"\")                                           // strip divider chars\n    .replace(/^[-=]{3,}\\s*$/gm, \"\")                              // strip --- === lines\n    .replace(/\\n{3,}/g, \"\\n\\n\")                                  // collapse 3+ newlines\n    .trim();\n}\n\nfunction MessageBubble({ msg, onApprove, onDismiss, t, isDark, onRate, onRegenerate }: any) {\n  const [copied, setCopied] = useState(false);\n  const isUser = msg.role === \"user\";\n\n  const copy = () => {\n    navigator.clipboard.writeText(msg.content);\n    setCopied(true);\n    setTimeout(() => setCopied(false), 2000);\n  };\n\n  return (\n    <motion.div initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }}\n      style={{ display:\"flex\", flexDirection: isUser?\"row-reverse\":\"row\", gap:10, alignItems:\"flex-start\", marginBottom:16 }}>\n\n      {/* Avatar */}\n      {!isUser && (\n        <div style={{ width:30, height:30, borderRadius:10, background:`linear-gradient(135deg,${V.v500},#3D1C8A)`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0, boxShadow:`0 4px 12px ${V.v500}40` }}>\n          <Zap size={13} color=\"#fff\" fill=\"#fff\"/>\n        </div>\n      )}\n\n      <div style={{ maxWidth:\"82%\", minWidth:40 }}>\n        {/* Image attachment */}\n        {msg.imageUrl && (\n          <img src={msg.imageUrl} alt=\"attachment\"\n            style={{ maxWidth:\"100%\", maxHeight:200, borderRadius:12, marginBottom:6, objectFit:\"cover\", display:\"block\" }}/>\n        )}\n        {msg.fileName && !msg.imageUrl && (\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:6, padding:\"6px 10px\", borderRadius:8, background:isDark?\"rgba(255,255,255,0.06)\":\"#f5f3ff\", marginBottom:6, fontSize:11, color:t.muted }}>\n            <FileText size={12}/> {msg.fileName}\n          </div>\n        )}\n\n        {/* Message bubble */}\n        <div style={{\n          padding: isUser?\"10px 14px\":\"2px 0\",\n          borderRadius: isUser?\"16px 16px 4px 16px\":\"0\",\n          background: isUser?`linear-gradient(135deg,${V.v500},#3D1C8A)`:\"transparent\",\n          color: isUser?\"#fff\":t.text,\n          fontSize: 14,\n          lineHeight: 1.65,\n          position:\"relative\",\n        }}>\n          {msg.isStreaming && !msg.content ? (\n            <span style={{ display:\"flex\", alignItems:\"center\", gap:8, color:t.muted }}>\n              <span style={{ display:\"flex\", gap:3 }}>\n                {[0,1,2].map(i => (\n                  <motion.span key={i} style={{ width:6, height:6, borderRadius:\"50%\", background:V.v400, display:\"block\" }}\n                    animate={{ y:[0,-4,0] }} transition={{ duration:0.6, repeat:Infinity, delay:i*0.15 }}/>\n                ))}\n              </span>\n              <span style={{ fontSize:13 }}>KIRO is thinking</span>\n            </span>\n          ) : msg.isStreaming && msg.content ? (\n            <p style={{ margin:0, whiteSpace:\"pre-wrap\", wordBreak:\"break-word\" }}>\n              {cleanKIROContent(msg.content || \"\")}\n              <motion.span animate={{ opacity:[1,0] }} transition={{ duration:0.5, repeat:Infinity }}>▋</motion.span>\n            </p>\n          ) : (\n            <p style={{ margin:0, whiteSpace:\"pre-wrap\", wordBreak:\"break-word\" }}>{cleanKIROContent(msg.content || \"\")}</p>\n          )}\n\n          {/* Action cards */}\n          {msg.actions?.map((action: any, i: number) => (\n            <ActionCard key={i} action={action} onApprove={onApprove} onDismiss={onDismiss} t={t} isDark={isDark}/>\n          ))}\n\n          {/* Copy button */}\n          {!isUser && !msg.isStreaming && msg.content && (\n            <button onClick={copy}\n              style={{ position:\"absolute\", top:0, right:-28, width:22, height:22, borderRadius:6, border:`1px solid ${t.border}`, background:t.card, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", opacity:0.5 }}>\n              {copied ? <Check size={11} color={V.v400}/> : <Copy size={11} color={t.muted}/>}\n            </button>\n          )}\n        </div>\n\n        {msg.timestamp && !msg.isStreaming && (\n          <p style={{ fontSize:10, color:t.muted, margin:\"3px 0 0\", textAlign:isUser?\"right\":\"left\" }}>\n            {new Date(msg.timestamp).toLocaleTimeString(\"en-NG\",{hour:\"2-digit\",minute:\"2-digit\"})}\n          </p>\n        )}\n      </div>\n    </motion.div>\n  );\n}\n\nexport default function KIROChat({ storeId: propStoreId, initialMessage, compact, conversationId: initConvId, onConversationCreated }: KIROChatProps) {\n  const { user } = useAuthStore();\n  const token  = useAuthStore(s => s.accessToken);\n  const storeId = propStoreId || user?.stores?.[0]?.id || \"\";\n\n  const [messages,    setMessages]    = useState<Message[]>([]);\n  const [input,       setInput]       = useState(initialMessage || \"\");\n  const [greeting,    setGreeting]    = useState<any>(null);\n  const [isListening, setIsListening] = useState(false);\n  const [activeTab,   setActiveTab]   = useState<\"chat\"|\"import\"|\"skills\"|\"goals\"|\"pulse\">(\"chat\");\n  const [pulseCount,  setPulseCount]  = useState(0);\n\n  // Load pulse alert count\n  useEffect(() => {\n    if (!storeId) return;\n    const BASE = (process.env.NEXT_PUBLIC_API_URL || \"https://dropos-v2.onrender.com/api\");\n    const token = useAuthStore.getState().accessToken;\n    fetch(`${BASE}/kai/pulse?storeId=${storeId}`, { headers: token ? { Authorization: `Bearer ${token}` } : {} })\n      .then(r => r.json())\n      .then(d => setPulseCount((d.data || []).filter((a: any) => !a.read).length))\n      .catch(() => {});\n  }, [storeId]);\n  const recogRef = useRef<any>(null);\n\n  const handleVoice = () => {\n    const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;\n    if (!SR) return;\n    if (isListening) { recogRef.current?.stop(); setIsListening(false); return; }\n    const r = new SR();\n    r.continuous = false;\n    r.interimResults = true;\n    r.onresult = (e: any) => {\n      const t2 = Array.from(e.results).map((r2: any) => r2[0].transcript).join(\"\");\n      setInput(t2);\n    };\n    r.onend = () => setIsListening(false);\n    r.start();\n    recogRef.current = r;\n    setIsListening(true);\n  };\n  const [loading,     setLoading]     = useState(false);\n  const [convId,      setConvId]      = useState(initConvId || \"\");\n  const [attachment,  setAttachment]  = useState<{url?:string; cloudUrl?:string; base64?:string; type?:string; name?:string}|null>(null);\n  const [uploading,   setUploading]   = useState(false);\n  const [histLoaded,  setHistLoaded]  = useState(false);\n\n  const bottomRef = useRef<HTMLDivElement>(null);\n  const inputRef  = useRef<HTMLTextAreaElement>(null);\n  const abortRef  = useRef<AbortController|null>(null);\n  const fileRef   = useRef<HTMLInputElement>(null);\n\n  // Theme detection\n  const isDark = typeof document !== \"undefined\" && document.documentElement.classList.contains(\"dark\");\n  const t = {\n    bg:    isDark?\"#07050F\":\"#F4F2FB\",\n    card:  isDark?\"#181230\":\"#fff\",\n    border:isDark?\"rgba(255,255,255,0.07)\":\"rgba(107,53,232,0.08)\",\n    text:  isDark?\"#F0ECFF\":\"#130D2E\",\n    muted: isDark?\"rgba(240,236,255,0.45)\":\"rgba(19,13,46,0.55)\",\n    input: isDark?\"rgba(255,255,255,0.05)\":\"#fff\",\n  };\n\n  // ── Load conversation history on mount ──────────────────────────────────────\n  useEffect(() => {\n    if (!storeId || histLoaded) return;\n    setHistLoaded(true);\n\n    // If we have a specific conversationId, load it\n    if (convId) {\n      api.get(`/kai/conversation/${convId}`)\n        .then(r => {\n          const conv = r.data?.data;\n          if (conv?.messages?.length) {\n            setMessages(conv.messages.map((m: any) => ({\n              id:        m.id,\n              role:      m.role,\n              content:   m.content,\n              timestamp: m.createdAt,\n            })));\n          }\n        })\n        .catch(() => {});\n    } else {\n      // Load the most recent conversation for this store\n      api.get(`/kai/conversations?storeId=${storeId}`)\n        .then(r => {\n          const convs = r.data?.data || [];\n          if (convs.length > 0) {\n            const latest = convs[0];\n            setConvId(latest.id);\n            if (latest.messages?.length) {\n              setMessages(latest.messages.map((m: any) => ({\n                id:        m.id,\n                role:      m.role,\n                content:   m.content,\n                timestamp: m.createdAt,\n              })));\n            } else {\n              // Load full conversation\n              api.get(`/kai/conversation/${latest.id}`)\n                .then(r2 => {\n                  const msgs = r2.data?.data?.messages || [];\n                  setMessages(msgs.map((m: any) => ({\n                    id: m.id, role: m.role, content: m.content, timestamp: m.createdAt,\n                  })));\n                })\n                .catch(() => {});\n            }\n          }\n        })\n        .catch(() => {});\n    }\n  }, [storeId, convId, histLoaded]);\n\n  useEffect(() => {\n    // Use requestAnimationFrame for smooth scroll during streaming\n    const el = bottomRef.current;\n    if (el) requestAnimationFrame(() => el.scrollIntoView({ behavior: \"smooth\", block: \"end\" }));\n  }, [messages]);\n\n  // ── File upload ──────────────────────────────────────────────────────────────\n  const handleFile = async (file: File) => {\n    const isImage = file.type.startsWith(\"image/\");\n    const isPDF   = file.type === \"application/pdf\";\n    const isCSV   = file.type === \"text/csv\" || file.name.endsWith(\".csv\");\n\n    if (!isImage && !isPDF && !isCSV) {\n      toast.error(\"Only images, PDFs, and CSV files are supported\");\n      return;\n    }\n\n    setUploading(true);\n    try {\n      if (isImage) {\n        // Read as data URI locally — no network roundtrip, works offline\n        // The base64 is sent directly to KIRO for vision analysis\n        const dataUrl = await new Promise<string>((resolve, reject) => {\n          const reader = new FileReader();\n          reader.onload  = () => resolve(reader.result as string);\n          reader.onerror = () => reject(new Error(\"Could not read file\"));\n          reader.readAsDataURL(file);\n        });\n        setAttachment({ url: dataUrl, type:\"image\", name:file.name });\n      } else {\n        // Read as base64 for PDF/CSV\n        const base64 = await new Promise<string>((res,rej) => {\n          const r = new FileReader();\n          r.onload  = () => res((r.result as string).split(\",\")[1]);\n          r.onerror = rej;\n          r.readAsDataURL(file);\n        });\n        setAttachment({ base64, type: isPDF?\"pdf\":\"csv\", name:file.name });\n      }\n    } catch {\n      toast.error(\"Upload failed\");\n    } finally {\n      setUploading(false);\n    }\n  };\n\n  // ── Execute approved action ──────────────────────────────────────────────────\n  const handleRate = (msgId: string, positive: boolean) => {\n    // Rate limiting feedback - could send to analytics\n    console.log(\"Message rated:\", msgId, positive ? \"👍\" : \"👎\");\n  };\n\n  const handleRegenerate = async (msgId: string) => {\n    // Find the user message before this one and resend it\n    const msgIdx = messages.findIndex(m => m.id === msgId);\n    if (msgIdx < 1) return;\n    const prevUserMsg = messages.slice(0, msgIdx).reverse().find(m => m.role === \"user\");\n    if (prevUserMsg) {\n      // Remove the assistant message and regenerate\n      setMessages(p => p.filter((_, i) => i < msgIdx));\n      await send(prevUserMsg.content);\n    }\n  };\n\n  const handleApprove = async (action: any) => {\n    try {\n      const res = await api.post(\"/kai/action\", {\n        storeId, conversationId: convId,\n        actions: [{ ...action, approved: true }],\n      });\n      const result = (res.data?.data || res.data?.results)?.[0];\n      // Use human-readable messages from the server\n      const resultMsg: Message = {\n        id:        `action-${Date.now()}`,\n        role:      \"assistant\",\n        content:   result?.success\n          ? (result?.message || `Done. ${action.type.replace(/_/g,\" \")} completed.`)\n          : (result?.error   || \"Something didn't go as expected. Let me check what went wrong and try again.\"),\n        timestamp: new Date().toISOString(),\n      };\n      setMessages(p => [...p, resultMsg]);\n    } catch(e:any) {\n      toast.error(e.response?.data?.message || \"Action failed\");\n    }\n  };\n\n  const handleDismiss = (action: any) => {\n    setMessages(p => p.map(m => ({\n      ...m,\n      actions: m.actions?.filter(a => a !== action),\n    })));\n  };\n\n  // ── Send message ─────────────────────────────────────────────────────────────\n  const sendMessage = async (msg: string) => {\n    if (!msg.trim() || loading) return;\n    setInput(\"\");\n    const syntheticEvent = { target: { value: msg } } as any;\n    // Directly call the send logic with the provided message\n    const text = msg.trim();\n    if (!storeId) { toast.error(\"No store connected\"); return; }\n\n    // Build user message\n    const userMsg: Message = {\n      id:        `u-${Date.now()}`,\n      role:      \"user\",\n      content:   text,\n      timestamp: new Date().toISOString(),\n    };\n    setMessages(p => [...p, userMsg]);\n\n    const kiroMsg: Message = {\n      id:          `k-${Date.now()}`,\n      role:        \"assistant\",\n      content:     \"\",\n      isStreaming: true,\n      timestamp:   new Date().toISOString(),\n    };\n    setMessages(p => [...p, kiroMsg]);\n    setLoading(true);\n\n    // Start KIRO (same as send but with provided text)\n    const convId = initConvId || \"\";\n    const BASE = (process.env.NEXT_PUBLIC_API_URL || \"https://dropos-v2.onrender.com/api\");\n    const token = useAuthStore.getState().accessToken;\n    const body: any = { message: text, storeId, sessionId: convId || undefined };\n\n    try {\n      const streamRes = await fetch(`${BASE}/kai/smart-chat`, {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\", ...(token ? { Authorization: `Bearer ${token}` } : {}), Accept: \"text/event-stream\" },\n        body: JSON.stringify(body),\n        signal: abortRef.current?.signal,\n      });\n\n      if (!streamRes.ok) {\n        const err = await streamRes.json().catch(()=>({message:`Error ${streamRes.status}`}));\n        throw new Error(err.message || `Server error ${streamRes.status}`);\n      }\n\n      const isStream = streamRes.headers.get(\"content-type\")?.includes(\"text/event-stream\");\n      let full = \"\";\n      if (isStream) {\n        const reader = streamRes.body!.getReader();\n        const decoder = new TextDecoder();\n        while (true) {\n          const { done, value } = await reader.read();\n          if (done) break;\n          const chunk = decoder.decode(value, { stream: true });\n          const lines = chunk.split(\"\\n\");\n          for (const line of lines) {\n            if (!line.startsWith(\"data:\")) continue;\n            const raw = line.slice(5).trim();\n            if (!raw) continue;\n            try {\n              const parsed = JSON.parse(raw);\n              if (parsed.token) { full += parsed.token; setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, content: cleanKIROContent(full) } : m)); }\n              if (parsed.conversationId && !convId) { setConvId(parsed.conversationId); onConversationCreated?.(parsed.conversationId); }\n              if (parsed.actions?.length) { setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, actions:parsed.actions } : m)); }\n              if (parsed.done) {\n                const raw2 = parsed.cleanResponse || \"\";\n                const fc = raw2 ? cleanKIROContent(raw2) : undefined;\n                const fa = parsed.actions || [];\n                setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, isStreaming:false, ...(fc?{content:fc}:{}), ...(fa.length?{actions:fa}:{}) } : m));\n              }\n              if (parsed.error) throw new Error(parsed.message || \"KIRO error\");\n            } catch(e:any) { if (e.message && !e.message.includes(\"JSON\")) throw e; }\n          }\n        }\n      }\n      setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, isStreaming:false, content:cleanKIROContent(full)||m.content } : m));\n    } catch(e:any) {\n      if (e.name === \"AbortError\") {\n        setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, content:\"Cancelled.\", isStreaming:false } : m));\n      } else {\n        setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, content:e.message||\"Something went wrong.\", isStreaming:false } : m));\n      }\n    } finally { setLoading(false); }\n  };\n\n  const send = async (overrideMsg?: string) => {\n    const text = (overrideMsg || input).trim();\n    if (!text && !attachment) return;\n    if (loading || !storeId) return;\n\n    abortRef.current?.abort();\n    abortRef.current = new AbortController();\n\n    const displayText = text || (attachment ? \"📎 \" + (attachment.name || \"Image\") : \"\");\n    const userMsg: Message = {\n      id:        `u-${Date.now()}`,\n      role:      \"user\",\n      content:   displayText,\n      imageUrl:  attachment?.url,\n      fileName:  !attachment?.url ? attachment?.name : undefined,\n      timestamp: new Date().toISOString(),\n    };\n    const kiroMsg: Message = {\n      id:          `k-${Date.now()}`,\n      role:        \"assistant\",\n      content:     \"\",\n      isStreaming: true,\n      timestamp:   new Date().toISOString(),\n    };\n\n    setMessages(p => [...p, userMsg, kiroMsg]);\n    setInput(\"\");\n    setAttachment(null);\n    setLoading(true);\n\n    try {\n      // Build message - if only image, add a default prompt\n      const isPdfAttachment = attachment?.type === \"pdf\";\n      const isCsvAttachment = attachment?.type === \"csv\";\n      const finalMessage = text || (\n        attachment?.type === \"image\" || attachment?.url\n          ? \"Analyse this product image. Identify what it is, write a complete product listing with: name, description (3 paragraphs), suggested selling price in my store currency, category, and 5 bullet points. Then ask if you should add it to my store.\"\n          : isPdfAttachment\n          ? `Read this PDF document called \"${attachment?.name}\". Extract all useful information — if it is a supplier catalogue, list all products with prices. If it is an order sheet, show me the data. Give me a clear summary of what is in it.`\n          : isCsvAttachment\n          ? `Analyse this spreadsheet called \"${attachment?.name}\". Show me what data it contains and give me useful insights.`\n          : \"\"\n      );\n      \n      const body: any = { message: finalMessage, storeId, sessionId: convId || undefined };\n      \n      if (attachment?.url) {\n        if (attachment.url.startsWith(\"data:image/\")) {\n          // Extract base64 from data URI for KIRO vision\n          const parts  = attachment.url.split(\",\");\n          const mime   = parts[0].split(\":\")[1]?.split(\";\")[0] || \"image/jpeg\";\n          body.imageBase64      = parts[1];\n          body.imageMediaType   = mime;\n          body.imageUrl         = attachment.url; // for display\n        } else {\n          // Cloudinary URL - send as URL reference\n          body.imageUrl         = attachment.url;\n          body.message          = finalMessage + `\\n\\n[Image: ${attachment.url}]`;\n        }\n      }\n      if (attachment?.base64) {\n        body.fileBase64  = attachment.base64;\n        body.fileType    = attachment.type;\n      }\n      if (attachment?.name)   body.fileName    = attachment.name;\n\n      const streamRes = await fetch(`${BASE}/kai/smart-chat`, {\n        method:  \"POST\",\n        headers: {\n          \"Content-Type\":  \"application/json\",\n          \"Authorization\": `Bearer ${token}`,\n          \"Accept\":        \"text/event-stream\",\n        },\n        body:   JSON.stringify(body),\n        signal: abortRef.current.signal,\n      });\n\n      if (!streamRes.ok) {\n        const err = await streamRes.json().catch(()=>({message:`Error ${streamRes.status}`}));\n        throw new Error(err.message || `Server error ${streamRes.status}`);\n      }\n\n      const isStream = streamRes.headers.get(\"content-type\")?.includes(\"text/event-stream\");\n\n      if (isStream) {\n        const reader  = streamRes.body!.getReader();\n        const decoder = new TextDecoder();\n        let full = \"\";\n\n        while (true) {\n          const { done, value } = await reader.read();\n          if (done) break;\n          const chunk = decoder.decode(value, { stream:true });\n          const lines = chunk.split(\"\\n\");\n          for (const line of lines) {\n            if (!line.startsWith(\"data:\")) continue;\n            const raw = line.slice(5).trim();\n            if (!raw) continue;\n            try {\n              const parsed = JSON.parse(raw);\n              if (parsed.token) {\n                full += parsed.token;\n                setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, content:full } : m));\n              }\n              if (parsed.conversationId && !convId) {\n                setConvId(parsed.conversationId);\n                onConversationCreated?.(parsed.conversationId);\n              }\n              if (parsed.actions?.length) {\n                setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, actions:parsed.actions } : m));\n              }\n              if (parsed.done) {\n                // Use clean response — strip KIRO_ACTION + ugly divider lines\n                const rawContent = parsed.cleanResponse || \"\";\n                const finalContent = rawContent\n                  .replace(/━+/g, \"\")\n                  .replace(/^-{3,}\\s*$/gm, \"\")\n                  .replace(/^={3,}\\s*$/gm, \"\")\n                  .replace(/\\n{3,}/g, \"\\n\\n\")\n                  .trim() || undefined;\n                const finalActions = parsed.actions || [];\n                setMessages(p => p.map(m => m.id === kiroMsg.id ? {\n                  ...m,\n                  isStreaming: false,\n                  ...(finalContent ? { content: finalContent } : {}),\n                  ...(finalActions.length ? { actions: finalActions } : {}),\n                } : m));\n              }\n              if (parsed.error) {\n                throw new Error(parsed.message || \"KIRO error\");\n              }\n            } catch(e: any) {\n              if (e.message && !e.message.includes(\"JSON\")) throw e;\n            }\n          }\n        }\n\n        setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, isStreaming:false, content:full||m.content } : m));\n\n      } else {\n        // Non-streaming fallback\n        const data = await streamRes.json();\n        const reply = data.data?.message || data.message || \"No response\";\n        if (data.data?.conversationId && !convId) {\n          setConvId(data.data.conversationId);\n          onConversationCreated?.(data.data.conversationId);\n        }\n        setMessages(p => p.map(m => m.id === kiroMsg.id ? {\n          ...m, content:reply, isStreaming:false,\n          actions: data.data?.actions || [],\n        } : m));\n      }\n\n    } catch(e: any) {\n      if (e.name === \"AbortError\") {\n        setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, content:\"Cancelled.\", isStreaming:false } : m));\n      } else {\n        const errMsg = e.message || \"Something went wrong. Check your connection.\";\n        setMessages(p => p.map(m => m.id === kiroMsg.id ? { ...m, content:errMsg, isStreaming:false } : m));\n      }\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const clear = () => { setMessages([]); setConvId(\"\"); setHistLoaded(false); };\n\n  const handleKey = (e: React.KeyboardEvent) => {\n    if (e.key === \"Enter\" && !e.shiftKey) { e.preventDefault(); send(); }\n  };\n\n  return (\n    <div style={{ display:\"flex\", flexDirection:\"column\", height:\"100%\", position:\"relative\", fontFamily:\"system-ui,sans-serif\" }}>\n\n      {/* Messages */}\n      <div style={{ flex:1, overflowY:\"auto\", padding:compact?\"12px\":\"16px 20px\" }}>\n        {messages.length === 0 && (\n          <div style={{ padding:\"32px 20px 20px\" }}>\n            {/* KIRO greeting */}\n            <div style={{ display:\"flex\", gap:12, marginBottom:20 }}>\n              <div style={{ width:36, height:36, borderRadius:12, background:`linear-gradient(135deg,${V.v500},#3D1C8A)`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0 }}>\n                <Zap size={16} color=\"#fff\" fill=\"#fff\"/>\n              </div>\n              <div style={{ background:isDark?\"rgba(107,53,232,0.08)\":\"#F4F1FF\", borderRadius:\"4px 16px 16px 16px\", padding:\"12px 16px\", maxWidth:\"85%\" }}>\n                <p style={{ fontSize:14, color:t.text, margin:\"0 0 6px\", lineHeight:1.6, fontWeight:500 }}>\n                  {greeting?.contextLine || \"What are we working on today?\"}\n                </p>\n                {greeting?.storeContext?.pendingOrders > 0 && (\n                  <p style={{ fontSize:13, color:\"#EF4444\", margin:\"4px 0 0\", fontWeight:600 }}>\n                    ⚠️ {greeting.storeContext.pendingOrders} order{greeting.storeContext.pendingOrders > 1 ? \"s\" : \"\"} pending — needs attention.\n                  </p>\n                )}\n              </div>\n            </div>\n            {/* Quick action suggestions */}\n            <div style={{ display:\"flex\", gap:8, flexWrap:\"wrap\", paddingLeft:48 }}>\n              {(greeting?.quickActions?.length ? greeting.quickActions.map((a: any) => a.prompt) : [\n                \"What should I focus on today?\",\n                \"What products are trending in Nigeria?\",\n                \"Write me an Instagram caption\",\n                \"Show my pending orders\",\n              ]).map((prompt: string) => (\n                <button key={prompt} onClick={() => sendMessage(prompt)}\n                  style={{ padding:\"6px 14px\", borderRadius:99, border:`1px solid ${t.border}`, background:t.card, color:t.text, fontSize:12, cursor:\"pointer\", fontFamily:\"inherit\", whiteSpace:\"nowrap\" }}>\n                  {prompt.length > 38 ? prompt.slice(0,38) + \"…\" : prompt}\n                </button>\n              ))}\n            </div>\n          </div>\n        )}\n\n        {messages.map(msg => (\n          <MessageBubble key={msg.id} msg={msg} onApprove={handleApprove} onDismiss={handleDismiss} t={t} isDark={isDark}/>\n        ))}\n        <div ref={bottomRef}/>\n      </div>\n\n      {/* Attachment preview */}\n      {attachment && (\n        <div style={{ padding:\"8px 16px 0\", display:\"flex\", alignItems:\"center\", gap:8 }}>\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"6px 12px\", borderRadius:10, background:`${V.v400}12`, border:`1px solid ${V.v400}30`, flex:1 }}>\n            {attachment.type===\"image\" ? <Image size={13} color={V.v400}/> : <FileText size={13} color={V.v400}/>}\n            <span style={{ fontSize:12, color:t.text, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{attachment.name}</span>\n            {attachment.url && <img src={attachment.url} alt=\"\" style={{ width:28, height:28, borderRadius:6, objectFit:\"cover\", flexShrink:0 }}/>}\n          </div>\n          <button onClick={() => setAttachment(null)} style={{ width:26, height:26, borderRadius:8, border:\"none\", background:\"rgba(239,68,68,0.08)\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n            <X size={12} color=\"#EF4444\"/>\n          </button>\n        </div>\n      )}\n\n      {/* Input bar */}\n      <div style={{ padding:compact?\"8px\":\"12px 16px\", borderTop:`1px solid ${t.border}`, background:t.card }}>\n        <div style={{ display:\"flex\", gap:8, alignItems:\"flex-end\", padding:\"10px 12px\", borderRadius:16, border:`1.5px solid ${loading?V.v400:t.border}`, background:t.input, transition:\"border-color 0.2s\" }}>\n          {/* Attach button */}\n          <button onClick={() => fileRef.current?.click()} disabled={uploading}\n            style={{ width:30, height:30, borderRadius:8, border:`1px solid ${t.border}`, background:\"transparent\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0, opacity:uploading?0.5:1 }}>\n            {uploading ? <Loader2 size={14} color={t.muted} style={{animation:\"spin 0.8s linear infinite\"}}/> : <Paperclip size={14} color={t.muted}/>}\n          </button>\n\n          <textarea\n            ref={inputRef}\n            value={input}\n            onChange={e => setInput(e.target.value)}\n            onKeyDown={handleKey}\n            placeholder=\"Ask KIRO anything...\"\n            rows={1}\n            style={{ flex:1, background:\"transparent\", border:\"none\", outline:\"none\", resize:\"none\", fontSize:14, color:t.text, fontFamily:\"inherit\", lineHeight:1.5, maxHeight:120, overflow:\"auto\", paddingTop:2 }}\n            onInput={e => {\n              const el = e.target as HTMLTextAreaElement;\n              el.style.height = \"auto\";\n              el.style.height = Math.min(el.scrollHeight, 120) + \"px\";\n            }}\n          />\n\n          {/* Send / Stop */}\n          <button onClick={handleVoice} title=\"Voice input\"\n            style={{ padding:\"0 10px\", borderRadius:10, border:`1px solid ${t.border}`, background:\"transparent\", color:isListening?\"#7C3AED\":t.muted, cursor:\"pointer\", fontSize:16, height:44, flexShrink:0 }}>\n            🎙\n          </button>\n          <button onClick={() => loading ? abortRef.current?.abort() : send()}\n            disabled={!loading && !input.trim() && !attachment}\n            style={{ width:34, height:34, borderRadius:10, border:\"none\", background: loading?\"rgba(239,68,68,0.1)\": (input.trim()||attachment)?`linear-gradient(135deg,${V.v500},#3D1C8A)`:\"rgba(0,0,0,0.05)\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0, transition:\"all 0.2s\", opacity:(!loading && !input.trim() && !attachment)?0.4:1 }}>\n            {loading\n              ? <X size={14} color=\"#EF4444\"/>\n              : <Send size={14} color={(input.trim()||attachment)?\"#fff\":t.muted}/>}\n          </button>\n        </div>\n\n        <p style={{ fontSize:10, color:t.muted, textAlign:\"center\", marginTop:6, marginBottom:0 }}>\n          KIRO can make mistakes. Always verify important business decisions.\n        </p>\n      </div>\n\n      {/* Hidden file input */}\n      <input ref={fileRef} type=\"file\" accept=\"image/*,.pdf,.csv,.xlsx\"\n        style={{ display:\"none\" }}\n        onChange={e => { if(e.target.files?.[0]) handleFile(e.target.files[0]); e.target.value=\"\"; }}/>\n\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n}\n"};
let n=0;
